INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-polevoy-tsvetok',
  'Полевой цветок',
  (SELECT id FROM "Authors" WHERE name = 'Арбен Кардаш' ORDER BY id LIMIT 1),
  'mrd5/mrd5-polevoy-tsvetok.jpg',
  'data:image/jpeg;base64,',
  1600,
  1070,
  'Заира вышла, хлопнув изо всех сил тяжёлой бронированной дверью.',
  '[{"kind":"image","path":"mrd5/mrd5-polevoy-tsvetok.jpg","caption":"Иллюстрация Лены Солнцевой"},{"kind":"paragraph","text":"Заира вышла, хлопнув изо всех сил тяжёлой бронированной дверью."},{"kind":"paragraph","text":"— Теперь, пожалуй, она не вернётся, — сказал Джирас, обращаясь к цветку, привезённому им с работы. — Это было единственное умное решение за всю её жизнь — заставить меня поставить эту дверь… — ему понравилось, как громко она хлопнула."},{"kind":"paragraph","text":"Молодой мужчина бессильно раскинул руки, словно внутри у него что-то надломилось, и одним движением кинул на диван своё отяжелевшее тело. Как будто бы скинул с плеч неимоверный груз, хотя где-то в глубине не исчезало чувство беспокойства, как червяк точит. Впрочем, это не помешало ему окончательно расслабиться и задремать…"},{"kind":"paragraph","text":"Сегодня рабочий день Джираса выдался похожим на все остальные, ничем не примечательным и скучным. Но, собираясь домой, он принял неожиданное решение: забрать с собой растение."},{"kind":"paragraph","text":"У полевого цветка, название которого он не удосужился узнать, Джирас ножницами осторожно срезал прошлогодние сухие и тонкие листья, уныло свисавшие с края горшочка, и бросил в корзину для мусора под рабочим столом…"},{"kind":"paragraph","text":"«Нет, мы с Заирой чужие друг другу люди, — думал Джирас, поливая зелёный росточек, проклюнувшийся из засохшей земли в горшочке на подоконнике. — Мы разные, не сошлись характерами. Не маленькая зарплата и не отсутствие у меня богатого дяди послужили причиной её постоянных недовольства и озлобленности. Просто она такая. Сердце у неё холодное, в нём нет места радости…»"},{"kind":"paragraph","text":"Прошло более семи лет, как он женился на Заире."},{"kind":"paragraph","text":"С самого начала он почувствовал, что дни совместной жизни у них лишены радости, какой-никакой удовлетворённости, проходят впустую, но его долго не оставляла надежда, что в сердце жены пробудится любовь, у неё появится чувство уважения к мужу."},{"kind":"paragraph","text":"Однако Заира так и не оттаяла, оставаясь неизменно холодной. Как бы ни старался пылкий молодой муж быть с ней нежным и предупредительным (даже посвятил ей несколько стихотворений!), у них не сложились отношения, связывающие мужчину и женщину, мужа и жену."},{"kind":"paragraph","text":"Первая брачная ночь… Джирас, овладев невестой, не ощутил никакой ответной тяги, никакой вспыхнувшей в ней от близости страсти. Девственная невеста как бы без всякого желания, с непонятной холодностью стала женщиной и женой. А Джирасу, в котором всё бурлило и пламенело, показалось, что над ним ехидно посмеялись… Но он ничем не проявил своего разочарования, к чему его обязывал жизненный опыт, да и опыт общения с женщинами тоже."},{"kind":"paragraph","text":"Он был лет на семь старше Заиры и с высоты своих лет связал поведение невесты в постели с тем, что это у неё впервые… «Не все цветы распускаются одновременно, — успокоил он себя. — У каждого цветка своя пора»."},{"kind":"paragraph","text":"Тогда эта мысль ему понравилась, даже очень, но впоследствии, спустя годы, осознав, что обманулся, он пришёл к другому выводу: цветы могут засохнуть, не распустившись. Или, что хуже, ты и сорняк можешь принять за цветок…"},{"kind":"paragraph","text":"Джирас надеялся, что у них появится ребёнок и внесёт радость и оживление в их тусклую жизнь. Такую же надежду лелеяла и Заира. Но прошло несколько лет, надежда угасала, а молодая женщина превратилась в настоящую фурию. Не пошутит, не приласкает — во всём она противоречит мужу, всякое его слово выводило её из себя. В редкие минуты прояснялось её лицо, но как только муж, пользуясь этим, пытался прощупать дорожку к её сердцу, она тут же возвращалась в своё обычное состояние."},{"kind":"paragraph","text":"Когда он предложил Заире вместе пойти на обследование к врачу, она согласилась — впервые за всю их совместную жизнь. Оказалось, что в отсутствии ребёнка виновна она…"},{"kind":"paragraph","text":"После этого она как будто решила сделать жизнь мужа просто невыносимой. Спали они в разных комнатах своей двухкомнатной квартиры, что, впрочем, не мешало жене на каждом шагу третировать мужа."},{"kind":"paragraph","text":"Он немного запоздает, она принюхается: «Выпил?» — и, если даже не выпил, всё равно устроит скандал, а когда он ляжет спать, обшарит его карманы. В выходной он соберётся к друзьям, она, раскинув руки, станет в дверях:"},{"kind":"paragraph","text":"— Знаю я, куда ты спешишь! Не отпущу!"},{"kind":"paragraph","text":"— Хочешь — пойдём вместе!"},{"kind":"paragraph","text":"— Делать мне больше нечего, как смотреть на ваши пьяные рожи!"},{"kind":"paragraph","text":"Он, делая что-то по хозяйству, о чём-то спросит; она, взглянув исподлобья, отвернётся и ничего не ответит. Или пойдёт на кухню и, нарочно шумя и что-то громко напевая (хотя совсем не умеет петь), начнёт мыть посуду. Ему оставалось одно: пойти в ванную стирать свою одежду, чтобы успокоиться…"},{"kind":"paragraph","text":"К ним перестали ходить друзья и родственники, так как не раз становились свидетелями сцен, устраиваемых Заирой. И опять Джирас успокаивал себя: «Хорошо, что у нас нет детей. Каково им было бы с такой матерью?»"},{"kind":"paragraph","text":"Джирас стыдился соседей, ведь стены не могли скрывать то, что у них творилось. Он догадывался, что соседи знают о странных отношениях мужа и жены по тому, как с ним здоровались на улице, по обычным расспросам. Даже чувствовал, что его жалеют…"},{"kind":"paragraph","text":"Он садился в своей комнате, оцепенев, предавался мыслям, пытаясь разобраться в своих отношениях с женой, понять её, и каждый раз не мог в чём-либо обвинить себя. Часто в голову приходила мысль о разводе, но Заире открыто об этом не говорил — совесть не позволяла. Он сделал ей предложение, и теперь разрушить семью ему казалось не по-мужски. Он понимал, что такой шаг спасёт его от безрадостной и бесцельной жизни, но хотел, чтобы этот шаг сделала Заира. Однако она, кажется, не думала о разводе. Вот и оставалось Джирасу сидеть, оцепенев, и думать, чувствуя себя несчастным…"},{"kind":"paragraph","text":"Ему часто вспоминались слова руководителя его учреждения, Бенбеца[1]. Когда в коллективе разнёсся слух, что Джирас выбрал невесту и собирается её засватать, умудрённый жизнью Бенбец сказал: «Смотри, парень, не бери девушку из семьи, где нет отца или брата. Она не будет хорошей женой». Слова Бенбеца только рассмешили Джираса: не директор, а прямо ясновидящий, — у Заиры действительно не было ни брата, ни отца. Теперь Джирасу было не смешно, прав оказался шеф."},{"kind":"paragraph","text":"Поздно он понял, что поспешил со свадьбой. Отец с матерью настаивали: «Сыграем свадьбу, пока бабушка жива». Его женитьба, возможно, действительно продлила жизнь бабушке: теперь она не хочет умирать, не повидав правнука…"},{"kind":"paragraph","text":"Наверное, он и сам не мог не поспешить, познакомившись с Заирой. Девушка с ладной фигуркой, с большими карими глазами, со свисающей на спину длинной чёрной косой приглянулась ему с первой же встречи. А ровный пробор её причёски всколыхнул его душу: он вспомнил фотографию матери в молодости с таким же пробором…"},{"kind":"paragraph","text":"Они встретились в читальном зале библиотеки. Заира, затребовав нужную книгу, села позади Джираса. Спустя примерно час она спросила у него время. Тогда он и увидел её пробор. И впервые подумал, что ему пора жениться, ведь и родные настаивают… Он ответил и решил продолжить разговор, но Заира его не поддержала и ушла. И это Джирас счёл одним из достоинств девушки."},{"kind":"paragraph","text":"И в другой раз они встретились в читальном зале: он вежливо поздоровался, но не получил ответа. «Наверное, не услышала…» — подумал он. Не пытался заговорить; не понимал того, что читает, в голове крутилось: «Нельзя её упустить… Не из тех, кто ищет на стороне…»"},{"kind":"paragraph","text":"Он запомнил, когда девушка ушла в первый раз. Когда приблизилось то время, он сказал: «Девушка, семь часов вечера!»"},{"kind":"paragraph","text":"Заира громко рассмеялась, обнажив красивые белые зубы. Из библиотеки они вышли вместе. Джирас узнал, что Заира оканчивает университет и будет учительницей русского языка и литературы."},{"kind":"paragraph","text":"Остальные события промелькнули быстро."},{"kind":"paragraph","text":"Сыграли свадьбу. В учреждении, где он работал, пошли ему навстречу, помогли и родители: он купил двухкомнатную квартиру. Словом, новоиспечённая семья начала новую жизнь. Однако счастья в этой семье не оказалось."},{"kind":"paragraph","text":"На первых порах, охваченный всепоглощающей любовью, Джирас не вспоминал слова Бенбеца, не задумывался над тем, в какой же семье выросла Заира. Хотя и знал, что она живёт с матерью и двумя сёстрами, разведёнными с мужьями. Об отношениях её отца и матери он узнал уже после свадьбы."},{"kind":"paragraph","text":"Отец из-за постоянных скандалов в семье был лишён родительских прав. Детство Заиры нельзя было назвать безоблачным. Она не могла забыть, как отец за волосы протащил мать по двору, а потом замахнулся на неё топором за то, что мать поздоровалась с соседом… Трёх-четырёхлетняя Заира вцепилась в руку отца с криком: «Отпусти маму!» Отброшенная сильной рукой, она отлетела, как мяч, и головой ударилась об стену… После того случая она возненавидела отца и даже в случайно возникающих разговорах с матерью или сёстрами никогда не называла его отцом."},{"kind":"paragraph","text":"В поведении дочери что-то проглядывалось от характера ненавистного ей отца. Если случалось, что на улице или на базаре Джирас здоровался со знакомой женщиной, Заира набрасывалась на него: «Почему ты здороваешься с ней?!» Задумываясь о детстве Заиры, отрицательно повлиявшем на её психику в те далёкие годы, Джирас осознавал: ненависть маленькой девочки, направленная на отца, с возрастом, постепенно усиливаясь, распространилась на всех мужчин; Джирас же был одним из них. Другого объяснения их отношениям он не находил…"},{"kind":"paragraph","text":"Скандалы в семье учащались. Последний был из-за бронированной двери."},{"kind":"paragraph","text":"— Зачем она нам? — возразил жене Джирас. — На что воры позарятся?"},{"kind":"paragraph","text":"— Все устанавливают. Почему нам нельзя? Разве мы какие-нибудь бомжи?"},{"kind":"paragraph","text":"— Случайно захлопнешь бронированную дверь, говорят, потом её ни за что не откроешь."},{"kind":"paragraph","text":"— Другие как-то открывают, значит, и ты откроешь. Или ты не мужчина? — Заира не могла не уколоть мужа."},{"kind":"paragraph","text":"Джирас привык и уже не всегда чувствовал уколы жены. И нежелание его иметь бронированную дверь было связано не с маленькой зарплатой, ещё и выплачиваемой с опозданиями, и не с обычным: «Я мужчина, я так хочу!»"},{"kind":"paragraph","text":"Он видел: в городе все кому не лень устанавливают бронированные двери, тем самым отдаляясь друг от друга. Растёт недоверие между людьми, каждый пытается укрыться в собственной скорлупе. Как всё это могло ему нравиться?"},{"kind":"paragraph","text":"Да, времена настали лихие. Люди, не сумевшие спасти державу, стремились каждый по отдельности превратить свой дом в крепость. Менялись на глазах: вчера были одни, сегодня стали другие. Джирас же не хотел меняться, хотел хранить верность неписаным традициям горцев, хотел защитить сами обычаи отцов. И он не понимал, как люди, поддаваясь неверию, могут обесценивать себя… А требование жены он всё-таки выполнил — в надежде, что она станет добрее, ласковее, откровеннее…"},{"kind":"paragraph","text":"Была ещё одна причина всё усиливающемуся охлаждению отношений между мужем и женой, и она скрывалась в том самом полевом цветке, который Джирас сегодня привёз домой."},{"kind":"paragraph","text":"Несколько лет назад Заира увидела этот цветок у Джираса (он, конечно, понял: забежала, чтобы проверить, муж на работе или нет)."},{"kind":"paragraph","text":"— Что это такое? — спросила она, разглядывая длинные тонкие листья, тянущиеся вверх по оконным стёклам."},{"kind":"paragraph","text":"— Просто растение, — ответил Джирас."},{"kind":"paragraph","text":"— Не похож на домашний цветок."},{"kind":"paragraph","text":"— Полевой цветок, — подтвердил Джирас. — Как называется — не знаю…"},{"kind":"paragraph","text":"Он скрыл от жены, что сам придумал название для своего цветка."},{"kind":"paragraph","text":"— Откуда он у тебя? — спросила Заира, хотя знала, какой последует ответ."},{"kind":"paragraph","text":"— Чимназ дала. Я же тебе рассказывал…"},{"kind":"paragraph","text":"Лицо Заиры помрачнело. Джирас знал: не потому, что вспомнила о безвременной кончине Чимназ."},{"kind":"paragraph","text":"— Выкинь его! Принадлежавшее покойникам не держат у себя."},{"kind":"paragraph","text":"— Это подарок, — возразил Джирас. — Она подарила, когда была ещё живая."},{"kind":"paragraph","text":"Заира ушла обиженная и дома не заговорила с мужем. «Хорошо, что обошлось без скандала», — успокоился Джирас."},{"kind":"paragraph","text":"С цветком и Чимназ связана отдельная история. Что-то Заира знала из этой истории, но не всё. Всё знал Джирас и хранил это в глубинах своего сердца, окутав нежностью и уважением. Вот отчего порой казалось, что сердце у него болит: он испытывал вину перед Чимназ. Чем больше охлаждались его отношения с Заирой, тем сильнее давало о себе знать это чувство."},{"kind":"paragraph","text":"Чимназ сидела в соседнем от Джираса кабинете."},{"kind":"paragraph","text":"Сегодня Джирас уже не сомневается, что в небольшом коллективе (около тридцати человек, большинство — женщины) только она могла додуматься принести полевой цветок с неизвестным названием и приучить его к домашним, точнее, рабочим условиям. Остальные женщины учреждения, попав под влияние наступившего лихолетья, перестали обращать должное внимание на растения в своих кабинетах; и даже на работу позволяли себе приходить неаккуратно. Директор, в коллективе за глаза прозванный Бенбецом, не имея возможности выплачивать вовремя работникам зарплату, не мог никого упрекнуть и на всё закрывал глаза."},{"kind":"paragraph","text":"Такое положение дел, казалось, устраивало всех."},{"kind":"paragraph","text":"В коллективе не стало прежней сплочённости. Товарищи на работе не видели друг друга неделями и месяцами, не знали, кто как живёт и чем занимается, вместе сходились через два-три месяца, в день выплаты хронически задерживаемой зарплаты. На эту зарплату невозможно было выжить: многие подрабатывали на стороне, но и привычную работу не решались бросить. Не оставляла надежда — а вдруг вернутся лучшие времена? Однако женщины перестали обращать внимание на цветы в кабинетах."},{"kind":"paragraph","text":"О заброшенных цветах позаботилась Чимназ: она собрала их и перенесла в свой кабинет, начала за ними ухаживать. И цветы ожили! Приходя на работу, если день выдавался погожий, Чимназ выносила горшки с цветами на просторную стеклянную веранду. Постороннему человеку, попавшему сюда, могло показаться, что здесь, в конце веранды, открыт цветочный магазин."},{"kind":"paragraph","text":"Однажды так и случилось."},{"kind":"paragraph","text":"— Цветы продаются? — спросил некий молодой человек."},{"kind":"paragraph","text":"— Да, — не растерялась Чимназ, белозубо улыбаясь. — Можете купить!"},{"kind":"paragraph","text":"По звонкому смеху и ясной улыбке женщины молодой человек догадался, что ошибся."},{"kind":"paragraph","text":"— Берите! — удержала его Чимназ. — Я пошутила. Мы не продаём, мы их дарим."},{"kind":"paragraph","text":"Молодой человек походил возле цветов. Заглянул и в кабинет."},{"kind":"paragraph","text":"— Ого! — воскликнул он. — Да тут целый оазис. Какой можно забрать?"},{"kind":"paragraph","text":"— Какой угодно, — Чимназ продолжала улыбаться и совсем расщедрилась. — Берите, сколько хотите."},{"kind":"paragraph","text":"У молодого человека в одной руке появился горшок с геранью, а в другой — кактус с длинными узкими отростками."},{"kind":"paragraph","text":"Джираса удивило, что незнакомец вот так просто взял цветы и ушёл. А Чимназ, видя его недоумение, весело прокомментировала:"},{"kind":"paragraph","text":"— Один — жене, другой — тёще, — она засмеялась. — А какой — кому, сам догадайся."},{"kind":"paragraph","text":"— Нет, — не согласился Джирас. — Один — жене, другой — любовнице. А какой — кому, сама подумай."},{"kind":"paragraph","text":"— Вы, мужчины, не можете без любовниц, — Чимназ уже не улыбалась."},{"kind":"paragraph","text":"— Ну, пусть не любовница, — Джирас смягчил свои слова. — Пусть будет просто приятная женщина, которая нравится. Ну, любимая."},{"kind":"paragraph","text":"— Вот это другое дело… Главное, чтобы любимая…"},{"kind":"paragraph","text":"В глубине глаз Чимназ, которая вновь заулыбалась, Джирас впервые заметил промелькнувшую печаль."},{"kind":"paragraph","text":"«Как, и у неё?.. Красивая женщина с семьёй и двумя детьми (хотя по её внешнему виду никто бы этого не предположил), умеющая подать себя с безупречным, для своего пола, достоинством, тоже заставляет себя скрывать в глубине глаз печаль?.. Наверное, я давно не заглядывал в глубины женских глаз… Жизнь, понимаешь. Что-то мы видим, но многое не замечаем. Что только не кроется в людских сердцах, особенно женских… А вот Заира не умеет, как Чимназ, скрывать то, что у неё в сердце…» — думал Джирас."},{"kind":"paragraph","text":"Незадолго до этого произошли и другие важные события."},{"kind":"paragraph","text":"Бенбец не желал, чтобы их учреждение, как и многие другие, рухнуло. Держался за должность — пусть возглавляемый им коллектив был мал, он дорожил им."},{"kind":"paragraph","text":"Несколько лет назад он вышел на пенсию, но продолжал работать. Он действительно походил на улитку: лысый, в больших очках с толстыми стёклами; лоб прорезан глубокими морщинами, над каждым глазом крупные с орешек бородавки; в светло-коричневом обвисшем костюме, ноги его плохо слушаются, ходит сгорбясь, выставив голову вперёд, — чем не улитка, у которой разбилась раковина? Но подобное сходство в коллективе подметили потом, прозвищем его наградили раньше, по другому поводу."},{"kind":"paragraph","text":"Бенбеца в советские времена откуда-то пригласили и поставили во главе учреждения. Чаще всего с языка директора слетало слово «улыбка». Но в его речевом аппарате с этим словом, как и со всеми русскими словами, происходило нечто невообразимое. Каждый раз, собирая в своём большом кабинете коллектив, он повторял, оголяя в улыбке свои золотые зубы: «В чалавеки самый дарагуй вещ — это улипка». Он желал, чтобы все сотрудники исполняли свои обязанности постоянно улыбаясь. За это над ним за глаза подтрунивали, но нельзя сказать, что его не любили."},{"kind":"paragraph","text":"Как-то после очередного совещания, когда все разошлись по своим кабинетам, Чимназ зашла к Джирасу и сказала:"},{"kind":"paragraph","text":"— Девушки со мной согласны, все помирают со смеху, — она и сама мелодично смеялась. — Интересно, что ты скажешь."},{"kind":"paragraph","text":"— О чём? — удивился Джирас."},{"kind":"paragraph","text":"— Наш «улипка» ведь похож на «улитку»…"},{"kind":"paragraph","text":"Джирас недолго соображал и тоже расхохотался."},{"kind":"paragraph","text":"— Особенно если без очков, — он вытер выступившие на глазах слёзы. — Правда, без раковины…"},{"kind":"paragraph","text":"Как бы то ни было, прозвище не мешало коллективу относиться к своему руководителю с должным уважением. Особенно его ценили в наступившие годы неразберихи. Бенбец не растерялся, сумел удержать учреждение на плаву, сохранить коллектив, хоть и с потерями. Кто только ни пытался отобрать небольшое здание, в котором находилось учреждение! Начиная с министров и высокопоставленных милицейских начальников, кончая ворами и грабителями… Но Бенбец выстоял, словно «улитка» и без раковины была защищена стальным панцирем. На своих плохо гнущихся ногах, неспешными шагами он доходил до кабинетов высшей власти и там сумел доказать необходимость сохранения учреждения, найти покровителей. В конце концов, соперники вынуждены были оставить его в покое."},{"kind":"paragraph","text":"В коллективе же были уверены, что он и без высоких покровителей добился бы своего, потому что он, Бенбец, был таким: непонятливым в своих действиях, пронырливым, умеющим дёшево купить и дорого продать, к мулу приспособить седло коня, стричь шерсть с яйца, завязать зёрнышко узелком. В трудные годы такой покровитель казался даром, ниспосланным небом, и его нельзя было не ценить."},{"kind":"paragraph","text":"Бенбец и сам знал себе цену. Ему было известно его прозвище, но он не подавал виду. Он был спокоен: его уже никто не трогал, он сохранил своё учреждение, остался на своей должности, а до всего прочего ему не было никакого дела. Между коллективом и руководителем действовало неписаное соглашение: каждый делает, что хочет, но старается показать, что учреждение работает, требуемое исполняется без промедления. И получает зарплату, когда дают."},{"kind":"paragraph","text":"Бенбец не препятствовал тому, чтобы его работники подрабатывали на стороне — всё же человек имел доброе сердце."},{"kind":"paragraph","text":"Ещё директор любил отмечать праздники. Почти в каждый праздник он собирал коллектив вместе, организовывал весёлые застолья с песнями и плясками. Любил быть тамадой и открывал застолье привычными словами: «В чалавеки самый дарагуй вещ — это улипка». Тут же устанавливалась соответствующая атмосфера, вспыхивали шутки и смех, забывались заботы и начиналось… И в плохие времена Бенбец не отказывался от застолий. Джирас получил в подарок от Чимназ полевой цветок после одного из таких праздничных застолий, последнего, в котором она участвовала."},{"kind":"paragraph","text":"…Новый год отмечали, как и все остальные праздники, в кабинете Бенбеца. В тот раз Чимназ выглядела красивее всех женщин. Когда она появилась в кабинете в отливающем серебром длинном платье, подчёркивающем красивые формы, с распущенными длинными чёрными волосами, — Джирас впервые почувствовал в её красоте нечто божественное. Привыкший обращаться с ней по-товарищески, позволяя себе лишь осторожные комплименты, — в этот раз он потерял дар речи. Он уже сидел, когда Чимназ возникла в дверях. Опять ему показалось, что в глазах её светится печаль, беспокойная, от кого-то или из-за чего-то скрываемая. А ещё, что в этих глазах мгновенно вспыхнул и погас свет, относящийся только к нему."},{"kind":"paragraph","text":"Он не ошибся."},{"kind":"paragraph","text":"— Я сяду рядом со своим соседом, — бесцеремонно обратилась Чимназ к сотруднику, сидевшему возле Джираса. — Ты не можешь разлучить соседей по кабинетам, коллега."},{"kind":"paragraph","text":"— Такой красавице как не уступить? — сотрудник встал и подал ей свой стул."},{"kind":"paragraph","text":"В тот день Чимназ нельзя было узнать, она пела и танцевала. Вставила в магнитофон кассету, которую принесла сама, — раздалась мелодия, берущая за душу. Чимназ пригласила на медленный танец Бенбеца. Тот даже забыл про обязанности тамады, вновь и вновь включая понравившуюся мелодию, долго не отпускал Чимназ... Бенбец медленно кружился в танце, Чимназ не противилась, каждый раз принимала его приглашение с улыбкой. «Она делает это в отместку кому-то, — думал Джирас. — Кому же, мужу? Разлад в семье?» Бенбец показывал золотые зубы, зажмурившись, склонял лысую голову к груди Чимназ, покачивающейся в танце. Джирасу хотелось встать, подойти к ним, врезать кулаком в очки Бенбецу, который был на голову ниже партнёрши. Но он поступил по-другому."},{"kind":"paragraph","text":"— Авторитарный режим ушёл в небытие, шеф, — пошутил он, подходя."},{"kind":"paragraph","text":"Оторвал его от Чимназ и сам стал танцевать с ней. И тени неудовольствия не появилось на лице Бенбеца."},{"kind":"paragraph","text":"— Я ничуть не против демократии, — поддержал он шутку и пригласил на танец сразу двух женщин."},{"kind":"paragraph","text":"Задвигался, обняв их за талии, склоняя голову к груди то одной, то другой… Чимназ улыбалась. Когда в кабинете стало тесно от танцующих пар, она спокойно опустила голову на плечо Джирасу, отчего ему показалось, что у него остановилось сердце. Он перестал чувствовать своё тело, словно они были двумя лепестками посреди безлюдного луга, полного цветов. В голове не осталось никаких мыслей… Когда-то им владело драгоценное желание, впоследствии забытое; теперь оно вернулось и может сбыться. И не было никаких ошибок, и та жизнь, где допускались ошибки, была не его жизнью, то был дурной сон. Настоящая его жизнь только начинается, и нет границ его счастью… Но танец завершился."},{"kind":"paragraph","text":"Застолье продолжалось до вечера, но подошло к концу, и всем показалось, что эти часы пролетели очень быстро. Джирас, как зачарованный, пришёл к себе в кабинет. Не совсем осознавая это, он чего-то ждал… Или он обманывает себя под действием выпитого?"},{"kind":"paragraph","text":"Да, он выпил, и ему только казалось, что Чимназ, как в танце, плавно покачиваясь своим гибким красивым телом, улыбалась, глядя на него…"},{"kind":"paragraph","text":"Но она на самом деле зашла в кабинет к нему. Не дождавшись со стороны Джираса ни слова, ни движения, Чимназ с лёгким упрёком сказала:"},{"kind":"paragraph","text":"— Обними же меня, Джирас! Не бойся…"},{"kind":"paragraph","text":"Только теперь, услышав слова, слетевшие с её красивых пухлых губ, Джирас понял, что всё происходит наяву, и выпитое тут ни при чём. Он растерялся ещё больше."},{"kind":"paragraph","text":"— Здесь ещё люди, нас увидят… Нехорошо… У нас семьи, Чимназ! — пытался оправдаться он."},{"kind":"paragraph","text":"В этот момент он ненавидел себя. «Трусливый дурак…»"},{"kind":"paragraph","text":"— Нет, Джирас, у нас не семьи, а бездонные ямы… Мы несчастные люди — и ты, и я…"},{"kind":"paragraph","text":"Она вплотную подошла к Джирасу, обняла его, погладила по голове и в долгом поцелуе прижалась к его губам. Оборвав поцелуй, она уставилась на Джираса своими глазами, полными слёз, и сказала:"},{"kind":"paragraph","text":"— Мы ничего не делаем для своего счастья. И не стараемся хоть что-нибудь делать…"},{"kind":"paragraph","text":"Чимназ ушла. Она долго не появлялась на работе. Джирас слышал, что она лежит в больнице с раком печени. Хотел навестить, но как он мог? После того, что у них было… «Ещё подумает, что я не хотел, потому что знал о её болезни… Она знает о моей семье, наверное, думает, что и я знаю о её проблемах…» Нет, даже признавая свою вину перед ней, он не решился навестить Чимназ."},{"kind":"paragraph","text":"Однажды она сама неожиданно появилась в его кабинете — высохшая, с поблёкшим лицом. Она ничем не напоминала ту Чимназ, что веселилась на новогоднем празднестве. Разве что глаза, правда, как будто увеличившиеся, оставались прежними. И печаль в этих глазах она уже не хотела или не могла скрывать."},{"kind":"paragraph","text":"Чимназ держала в руках горшок с цветком. Джирас вскочил:"},{"kind":"paragraph","text":"— Чимназ, ты!.."},{"kind":"paragraph","text":"— Это тебе на память обо мне, — она не дала ему договорить. — Береги. Я ухожу."},{"kind":"paragraph","text":"— Как уходишь? Увольняешься с работы?"},{"kind":"paragraph","text":"— Как все уходят… — она поставила горшок с цветком на подоконник. — Поливай чаще. Это полевой цветок. Как называется, не знаю. С горы за нашим селом. Будешь ухаживать, привыкнет к домашним условиям. Даже зацветёт. Вот не знаю только, как называется."},{"kind":"paragraph","text":"— Я придумаю ему название."},{"kind":"paragraph","text":"Чимназ улыбнулась, больше ничего не говоря, и вышла из кабинета."},{"kind":"paragraph","text":"Как узнал Джирас, все цветы, которые Чимназ собрала в своём кабинете, она обратно раздала женщинам учреждения. После этого её никто не видел."},{"kind":"paragraph","text":"Ещё через полтора месяца пришла весть о её кончине. «Я ухожу… — вспомнил Джирас. — Как все уходят…»"},{"kind":"paragraph","text":"В его сердце, казалось, навсегда засело чувство неисправимой вины перед Чимназ. Ему оставалось одно: не забывать о её просьбе. И он не забывал. Каждый день, приходя на работу, поливал цветок. Он хорошо рос, украшая окно. Длинные узкие листья, увядшие осенью, Джирас осторожно срезал ножницами, а весной с нетерпением дожидался новых ростков… Но тот не зацветал."},{"kind":"paragraph","text":"«Может быть, он и не должен цвести, — думал Джирас. — Может быть, Чимназ просто так сказала, что он цветёт, чтобы я ждал? Чтобы я не забывал её, постоянно нёс в себе вину перед ней?»"},{"kind":"paragraph","text":"И вот опять он вспомнил слова Чимназ: «Будешь ухаживать, привыкнет к домашним условиям. Даже зацветёт…» Подумал: «Наверное, она держала его дома и знает… Но ведь рабочий кабинет — не дом», — неожиданно пришло в голову."},{"kind":"paragraph","text":"Тогда Джирас и решил отвезти полевой цветок домой, хотя и знал, что Заира разозлится…"},{"kind":"paragraph","text":"…Джирас очнулся от сердитого стука в дверь кулаком."},{"kind":"paragraph","text":"— Кто там? — он вышел в прихожую."},{"kind":"paragraph","text":"— Открой! — потребовал сердитый голос Заиры."},{"kind":"paragraph","text":"— Я и не закрывал. Дверь захлопнулась, — Джирас тщетно попытался открыть её. — Замок заклинило намертво. Позови кого-нибудь из коммунальной службы."},{"kind":"paragraph","text":"— Я никого не позову! — Заира стукнула в дверь ногой и стала спускаться по лестнице к выходу. Он понял это по стуку каблуков."},{"kind":"paragraph","text":"* * *"},{"kind":"paragraph","text":"На этом можно было поставить точку и завершить рассказ, потому что автор не считает нужным ещё что-либо сообщать об отношениях Джираса и Заиры, о том, как сложилась судьба их семьи."},{"kind":"paragraph","text":"Разве что читателю интересно будет узнать, как они поступили с захлопнувшейся бронированной дверью."},{"kind":"paragraph","text":"Джирас снял её и выбросил. Поставил другую."},{"kind":"paragraph","text":"Более важное событие в его жизни произошло однажды весной, буйно вошедшей в свои права: на полевом цветке выросли длинные, как шнуры, усики, расползшиеся по всему окну, и на них распустились мелкие жёлтые цветочки."},{"kind":"paragraph","text":"А ещё Джирас, копаясь в разных красочных энциклопедиях по флоре, узнал, что полевой цветок, оставшийся ему от Чимназ, называется просто осотом."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
