INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-rasputitsa',
  'Распутица',
  (SELECT id FROM "Authors" WHERE name = 'Глеб Кашеваров' ORDER BY id LIMIT 1),
  'mrd5/mrd5-rasputitsa.jpg',
  'data:image/jpeg;base64,',
  1600,
  923,
  'Тем утром на станции так больше никто и не появился. Ничего удивительного: уже за несколько дней до намечавшейся поездки участники начали отваливаться.',
  '[{"kind":"image","path":"mrd5/mrd5-rasputitsa.jpg","caption":"Иллюстрация Екатерины Ковалевской"},{"kind":"paragraph","text":"Тем утром на станции так больше никто и не появился. Ничего удивительного: уже за несколько дней до намечавшейся поездки участники начали отваливаться."},{"kind":"paragraph","text":"Две парочки, вписавшиеся последними, первыми заявили, что не собираются тратить все выходные на то, чтобы месить холодную грязь в каких-то ебенях. «Предпочли остаться в тепле, уюте и комфорте, понежиться в сухих постелях, сходить в кино, поиграть с друзьями в настолки, потусить в какой-нибудь кафешке или… На что там ещё сливают время эти \"ванильные неразлучники\"?! Тьфу, блин, аж противно!»"},{"kind":"paragraph","text":"Хотя… Вот положа руку на сердце — неизвестно, как бы он сам предпочёл провести эти дни, если бы не пришлось расстаться с Ликой… «Ладно, чёрт с ними! Меньше народу — спокойней поездка»."},{"kind":"paragraph","text":"На следующий день ещё трое участников отсеялись. Зачёт, простуда, обострение хронической лени ― у всех свои причины."},{"kind":"paragraph","text":"Дальше — больше: когда объявили прогноз погоды, разразилось бурное обсуждение, и один за другим потенциальные туристы пришли к выводу, что в гробу они видали эту грёбаную авантюру. Что самое «замечательное», Макс (и ты, Брут?!) взял самоотвод далеко не самым последним… Тот самый Макс, который это всё затеял, всех подбил скататься на лоно природы, Макс ― единственный, кто лично был знаком со всеми участниками несостоявшейся тургруппы, который убеждал, что ехать надо «по-любасу», невзирая ни на что… Вот этот человек написал лаконичное: «Чё-то как-то нах, расходимся». Естественно, вслед за ним и остальные посыпались."},{"kind":"paragraph","text":"Так Кирилл оказался на вокзале в гордом одиночестве."},{"kind":"paragraph","text":"У пригородных касс, несмотря на ранний час, уже собралась небольшая очередь. Добравшись до окошка, он взял билеты до нужного пункта для себя и для велосипеда и двинул на платформу."},{"kind":"paragraph","text":"Было зябко, серо, порывистый ветер то и дело бросал в лицо редкие дождевые капли и доносил букет ароматов креозота, дизеля, угля и недотаявшего снега."},{"kind":"paragraph","text":"Вскоре подали электричку. Чисто чтобы «потроллить этих нежножопых олухов», Кирилл сделал «себяшку» с гордо поднятым средним пальцем и скинул в чат. Разместившись в вагоне, отбил ехидное: «Пакеда, чмошники!», а немного подумав, дописал ещё: «Лучше ехать соляком, чем с таким, как вы, говном!»"},{"kind":"paragraph","text":"Довольный результатом, он развалился на сиденье и начал наблюдать за редкими людьми, суетливо снующими на перроне. На контрасте с ними собственное спокойствие ощущалось более глубоким."},{"kind":"paragraph","text":"Вагон, так и не наполнившись пассажирами, тронулся. В нём разместились несколько тёток, попытавшихся при входе неодобрительными взглядами сжечь велосипед; дедок в бледно-выцветшей фуражке и с почерневшей от времени корзиной в руках; изрядно перебравший мужик в бушлате, уснувший у окна ещё до отправления электрички."},{"kind":"paragraph","text":"Когда электропоезд прибыл на нужную станцию, смурная предутренняя серость уже превратилась в серость утра пасмурного дня. Моросить почти перестало."},{"kind":"paragraph","text":"За двухминутную стоянку Кирилл успел выволочь на построенную чуть выше уровня земли платформу свой нагруженный пищей и снаряжением велосипед, пристроиться вместе с ним у сохраняющего видимость окрашенности ограждения и начать распаковывать пакет с перекусом."},{"kind":"paragraph","text":"Как известно, голод — лучшая приправа… Но есть, как назло, особенно-то и не хотелось; с другой стороны, перспектива тащить лишние граммы припасов привлекала ещё меньше ― везти еду в себе намного легче. Поэтому Кирилл, меланхолично оглядывая окрестности, чисто механически уничтожил лишний груз — бананы, холодный кефир, каким-то чудом уже разломавшиеся печеньки…"},{"kind":"paragraph","text":"Велосипед напоминал навьюченное животное, отбившееся от каравана. Задняя его часть была нагружена сумкой, скрывшей и багажник, и бо́льшую часть колеса. Как будто этого было недостаточно, конструкцию венчал скрученный туристический коврик. В треугольник между трубами рамы аккуратно вписалась сумочка с ремкомплектом, бутылкой воды и всякими мелочами. Даже под рулём была приторочена скатка с тентом и набором для костра. Это даже с учётом того, что Кирилл решил не брать палатку и топор, а обойтись костром и валежником."},{"kind":"paragraph","text":"«Чёрт, как же много нужно человеку, чтобы за пару дней на природе не сдохнуть!» — философски подумал он, снимая гружёный велосипед с платформы."},{"kind":"paragraph","text":"Когда поселковые постройки скрылись из виду и сырой асфальт, зажатый лесом, повёл длинными дугами поворотов и волнами холмов прочь от цивилизации, Кирилл почти физически почувствовал, как внутри расслабляется туго сжатая ментальная пружина, из-за постоянного напряжения почти незаметная в обычное время."},{"kind":"paragraph","text":"Под пока ещё редкий щебет птиц, под мерное жужжание протектора, своими мелкими зубами пожирающего метры дороги, под ритмичное щёлканье педали, — которую, по-хорошему, давно бы надо было или починить, или выкинуть, — наступило состояние, близкое к медитации или даже просветлению. Всё растворилось в новом ощущении: и лёгкое негодование на несостоявшихся попутчиков, и лихое желание написать им ещё что-нибудь желчное и разухабистое, и чувство вины и обиды от недавно прервавшихся отношений с девушкой, и суетные ежедневные заботы… Всё это растаяло, как ноздреватый весенний снег. Но, в отличие от него, не оставило ни капли грязи. Стало легко, светло и отрадно."},{"kind":"paragraph","text":"Как будто резонируя с этим душевным состоянием, начала налаживаться и погода. Серый занавес там наверху чуть раздвинулся, и в прорехи деликатно заглянуло несколько солнечных лучей. Ветер взял передышку, успокоился, но вскоре начал дуть более или менее в спину. Лес вдоль дороги веял обманчивым ощущением тепла и уюта, какое наполняет сумрачный холодный дом, когда в нём включают электрическую лампочку."},{"kind":"paragraph","text":"Несмотря на беззаботное настроение, за дорогой тоже надо было следить. Нет, пропустить нужный поворот здесь было невозможно. Просто изредка, поднимая в воздух тучи мелких брызг, мимо проносились машины, и в эти моменты требовалось быть предельно внимательным и собранным — мало ли что…"},{"kind":"paragraph","text":"Но всему хорошему рано или поздно приходит конец. Вот и хорошая дорога кончилась. Вернее, асфальт был проложен и дальше, только теперь уже он перестал быть попутным. Велосипед бодро соскочил с твёрдого покрытия и, сытно чавкнув, натужно заскользил по весенней разъезженной грязи, норовя уйти в занос или просто упасть. Метров через сто попался участок дороги посуше, потом снова грязь, и так — несколько километров. Путь, который предполагалось одолеть за полчаса и без особого труда, отъел часа два и утомил ужасно."},{"kind":"paragraph","text":"Наконец ветер принёс запах дыма, и скоро вслед за этим знаком близости жилья начали появляться и сами домики. Здесь Кирилл планировал купить что-нибудь съестное и, выехав за околицу, спокойно перекусить где-нибудь вне досягаемости лишних глаз. План пришлось менять: время подступило почти к обеду, а отдых был нужен срочно. Было решено устроить привал тут же, на гравийном пятачке, притулившемся за магазином, — что и было незамедлительно исполнено. К счастью, оспорить решение было решительно некому. Иногда сырой весенний ветер, споткнувшись о выцветшую постройку, попадал в этот закуток и, взвихрив прошлогодний мусор и погремев для острастки жестью крыши, выстуживал прилипшую к коже пропотевшую одежду. И хотя лучи солнца то и дело просеивались сквозь решето низких туч, тепла они не прибавляли."},{"kind":"paragraph","text":"Кирилл в очередной раз пристрастно вгляделся в цифры на дисплее велокомпьютера — будто тот мог изменить свои показания в его пользу, как неуверенный свидетель. Но этот маленький чёрный коробочек отмерял часы и километры, не пытаясь угодить своему владельцу."},{"kind":"paragraph","text":"«Если так и дальше пойдёт, проще прямо сейчас обратно повернуть», — подумал Кирилл."},{"kind":"paragraph","text":"И правда, это был последний шанс сойти с маршрута — посёлок был на перепутье: кроме того, что здесь проходила дорога к точке, куда Кирилл ехал изначально, отсюда можно было свернуть к трассе, по которой в итоге выехать к междугороднему автобусу, или же можно повернуть обратно, в сторону железнодорожной станции. Но вернуться не позволяли два чувства. С одной стороны — гордость и нежелание признать правоту тех, кто ещё в городе понял бесперспективность этой затеи. С другой — желание преодолеть маршрут и снова увидеть замечательное, маленькое и крайне непопулярное озерко неподалёку отсюда. Туристы обычно ездят мимо, или не доезжая, или проезжая дальше — сворачивают к более крупным и потому считающимся более живописными озёрам. Поэтому вокруг этого маленького карстового озерка больше дров и меньше мусора, а заодно и шансов встретить шумную компанию, которая испортит отдых."},{"kind":"paragraph","text":"Победили чувства, а не логика, и Кирилл, отобедав, двинулся в сторону лесной чащи."},{"kind":"paragraph","text":"То ли это решение было плохим, то ли звёзды сошлись неудачно. Планировалось добраться сильно засветло, разбить лагерь и развести костёр. Куда там! Под прикрытием леса зима ещё спорила с неотвратимостью весны. На дорогу то и дело выползали языки зернистого снега, с оглушительным в тишине шорохом рассыпавшиеся под колёсами, тут же выскакивали глубокие лужи шириной в обе колеи и длиной в несколько метров. Ну чем не озеро? Хоть тут, на обочине, разбивай лагерь."},{"kind":"paragraph","text":"Даже несмотря на качество дороги, надежда остановиться на отдых более или менее вовремя ещё теплилась… Но тут случилась очередная неудача. Обломанный сухой сучок, притаившийся в грязи, пробил колесо. Один шанс на миллион — и на тебе! Пришлось остановиться, чтобы поменять камеру, — благо, была на всякий случай в ремнаборе."},{"kind":"paragraph","text":"Только он справился с возникшей неурядицей, проехал пару километров — и новая напасть. Так давно хрустевшая педаль решила, наконец-то, умереть, причём сделать это максимально ярко. Она внезапно заклинила, нога не удержалась, и шатун, по инерции провернувшись, пребольно заехал этой самой педалью сзади по голени. Яростно матерясь и прихрамывая, Кирилл оттащил велосипед на место посуше и стал искать решение проблемы. Новую педаль найти, естественно, было негде, да и инструментов было с собой, всё-таки, недостаточно. Оставалось одно: сделав из палки покрепче рычаг, он примерился и надавил что было силы. Что-то жалобно хрустнуло, поддалось… Да, теперь педаль болталась под ногой и казалось, что она того и гляди ускачет в лужу, как не вовремя проснувшаяся лягушка, — но хотя бы больше не клинила."},{"kind":"paragraph","text":"За всеми этими приключениями незаметно наступил вечер. Солнце, и так не слишком хорошо видное за деревьями, скрылось совсем. Начало стремительно темнеть. До намеченного озера оставалось ещё с полкилометра, когда впереди в загустевших сумерках замелькали сполохи, отбрасываемые медленно приближающимися фарами."},{"kind":"paragraph","text":"Оказаться в таких местах и в такое время могли либо охотники, либо туристы, либо лесники. Вероятность встречи с последней категорией граждан вызывала смутное беспокойство."},{"kind":"paragraph","text":"«Да ну вас на хер», — здраво рассудил Кирилл."},{"kind":"paragraph","text":"Он торопливо выскочил из колеи и, отойдя несколько метров от дороги, спрятал свой транспорт и притаился за удачно подвернувшимися кустами можжевельника."},{"kind":"paragraph","text":"На удивление, вместо одной машины, осторожно переваливаясь по ухабам и расплёскивая жидкую грязь, мимо проползла целая разномастная кавалькада из отечественных и иностранных внедорожников, украшенных цветами и лентами."},{"kind":"paragraph","text":"Подождав, пока последняя машина скроется из виду, Кирилл покинул своё убежище и продолжил путь, удивляясь про себя своеобразности встреченной процессии."},{"kind":"paragraph","text":"* * *"},{"kind":"paragraph","text":"Окрестности озера тонули в ночи, наползающей из густых теней. Отыскав местечко, хотя бы намекающее на сухость, Кирилл бросил вещи и, вооружившись фонариком, отправился за дровами. Вскоре возле будущего бивака выросла целая куча веток."},{"kind":"paragraph","text":"Валежник в основном был сырым, но сухие тонкие веточки, сложенные под ним шалашиком, занялись очень быстро, и сыроватые толстые ветки, уложенные вокруг и сверху, начали нехотя дымиться, обугливаться — и наконец загорелись, распространяя вокруг себя тепло и удушливый дым."},{"kind":"paragraph","text":"Стало уютней. Больше всего теперь хотелось сесть у костерка, протянуть к нему руки и просто отдыхать. Но расслабляться пока ещё было не время. Преодолевая усталость, пытавшуюся взять над ним верх, Кирилл растянул невдалеке от огня тент, положил коврик, придавив его ветками, и — самое нелёгкое — выкарабкался из мокрой одежды и надел запасную, сухую, но пока холодную. Оставалось только сходить за водой."},{"kind":"paragraph","text":"Прихватив свой литровый котелок и несколько печенек, он поплёлся к озеру, хрустя едой и ветками."},{"kind":"paragraph","text":"Балансируя на склизком берегу и пристально глядя себе под ноги, Кирилл сумел спуститься к самому урезу воды и, держась за прибрежные кусты, зачерпнул её котелком. Несмотря на темноту, обстановка казалась живописной. Вода была ещё чернее, чем ночь, и проглатывала луч ручного фонарика, стоило ему чуть отступить от берега. А вот вдоль её поверхности свет легко перелетал через всё озеро и без труда обшаривал противоположный берег, разбиваясь о стволы деревьев и теряясь среди них. Поддавшись внутреннему порыву, Кирилл бросил одно из печений в воду, и оно, размокнув, медленно кануло в глубину."},{"kind":"paragraph","text":"На другом берегу луч высветил сугроб у уреза воды — низкий, причудливый, развалившийся на тонкие язычки и оттого похожий чем-то на фигуру лежащего человека. Скользнул дальше, но замер и, поколебавшись, метнулся обратно. Нечто в круге света напоминало труп до такой степени, что становилось жутко до тошноты."},{"kind":"paragraph","text":"Кирилл вернулся к костру, поддержал уже начавший задыхаться огонь, поставил греться котелок с водой… Но наваждение всё никак не выходило из головы — перед глазами стоял образ трупа, лежащего прямо рядом с лагерем. Чтобы избавиться от этой навязчивой галлюцинации, нужно было посмотреть на этот сугроб вблизи, встать возле него, зачерпнуть горсть смёрзшегося и подтаявшего снега и бросить в воду или пнуть наотмашь, чтобы холодные искры льда разлетелись от удара и исчезли в темноте вместе с осколками страшной иллюзии."},{"kind":"paragraph","text":"Не в силах больше сопротивляться, Кирилл решил снова отправиться к берегу. Откуда-то из глубин подсознания поднялось безотчётное чувство опасности. Впервые за эту поездку он пожалел, что не взял топор. В качестве компромисса, в дополнение к совершенно несерьёзному ножу он положил в карман телефон… Как ни странно, от этого стало чуть спокойнее."},{"kind":"paragraph","text":"Он прошёл по дуге, обходя прибрежные заросли. Скоро в просвете между веток замелькало что-то белое, и перед ним оказался нужный пляж. Вот сейчас, совсем скоро проклятое воображение лишится оснований мучить его! Он решительно вынырнул из кустов на берег. И…"},{"kind":"paragraph","text":"Через несколько оглушительно тихих секунд сомнений не осталось — это действительно было человеческое тело."},{"kind":"paragraph","text":"«Ничего не трогать и бежать как можно дальше!» — вопил внутренний голос."},{"kind":"paragraph","text":"Но повиноваться ему у Кирилла не было сил, ― он словно провалился в трясину по пояс. Не в силах убежать или отвернуться, он против своей воли разглядывал представшее перед его взглядом."},{"kind":"paragraph","text":"Берег был испещрён следами ног. Тут и там валялись свечные огарки, цветы и монеты."},{"kind":"paragraph","text":"У границы воды лежало обнажённое женское тело, украшенное зелёным венком и обложенное такими же веточками."},{"kind":"paragraph","text":"Кирилл весь обратился в зрение. Ему показалось, что он смотрит на эту неизвестную вплотную. Что он видит каждый волосок и каждую мельчайшую пору на бескровной синевато-белой коже. Что он может разглядеть каждый листик на ветках, из которых сплетён венок, рассмотреть их зелёную восковитую верхнюю сторону и беловатый низ и даже извлечь из недр памяти совершенно бесполезную теперь информацию, что это растение называется подбел. Не мог только разглядеть её лица, укрытого распущенными волосами — наверное, это и к лучшему. И без того был готов извергнуть содержимое желудка…"},{"kind":"paragraph","text":"Он попятился было на негнущихся ногах, но снова замер. Лежащий у воды труп, кажется, пошевелился."},{"kind":"paragraph","text":"«Бред! Ну бред же!» — думал Кирилл, опять утративший способность двигаться."},{"kind":"paragraph","text":"Но секунд через десять бледное тело снова едва уловимо шелохнулось. Потом — ещё. Девушка явно дышала, хотя и слабо, еле заметно."},{"kind":"paragraph","text":"Мысли, пусть их и было мало, с огромной скоростью заметались в его голове, наводя страшный беспорядок."},{"kind":"paragraph","text":"«Вызвать МЧС!»; «Проверить пульс!»; «Что за хуйня?!»; «Не трогать улики!» и «Как бы самого не притянули…» — они кружили назойливым хороводом, не давая предпринять что-нибудь толковое."},{"kind":"paragraph","text":"Телефон всё равно не ловил, помощи ждать было неоткуда. В конце концов Кирилл решился и разогнал все посторонние мысли."},{"kind":"paragraph","text":"«Чаще всего на природе убивает холод», — вспомнилась ему фраза с какого-то форума."},{"kind":"paragraph","text":"Он осторожно подхватил тело и перенёс в лагерь."},{"kind":"paragraph","text":"«Блин, ну за что ж мне поеботина-то такая, а?!» — в бессильном гневе бормотал он себе под нос и, не находя ответа, делал, что до́лжно."},{"kind":"paragraph","text":"Снял с себя сухую и уже прогревшуюся одежду, с содроганием натянул дорожную — пропотевшую и стылую. Попытался в меру сил растереть бледную до синевы и холодную как лёд незнакомку, не подававшую никаких признаков жизни, кроме дыхания и подрагивания глаз под веками. Одел её в сухое и тёплое, завернул в прогретый у почти обессилевшего костра спальник, уложил на бок под тент и, ещё раз проверив, что она дышит, бросился в лес."},{"kind":"paragraph","text":"Пусть он не медик и не спасатель, но сейчас от него требуется обеспечить человека, попавшего в беду, тем, что сейчас важнее всего, — теплом. Нужно было найти дрова получше, которые горели бы нормально, а не гасли каждые десять минут. По крайней мере, это ему под силу!"},{"kind":"paragraph","text":"Стараясь не слишком далеко отходить от лагеря, он обшарил все кусты и деревья в поисках сухих, но не упавших веток, и при этом, желательно, потолще. Набрав охапку таких, он вернулся, накидал в огонь нового топлива и, убедившись, что костёр горит, перевернул девушку на другой бок. После — снова отправился в ночной лес. И так несколько раз, пока гора дров не была признана достаточной, чтобы гореть до утра."},{"kind":"paragraph","text":"Наконец он позволил себе отдохнуть. Натруженные ноги ощущались ватными, а ладони саднило от царапин и заноз."},{"kind":"paragraph","text":"С полчаса он просидел, тупо глядя перед собой и отгоняя предположения о том, что же тут случилось. Но стоило ему отвлечься, как в памяти всплыли украшенные внедорожники, и он, облившись холодным потом, поблагодарил свою интуицию, подсказавшую не попадаться на глаза их пассажирам…"},{"kind":"paragraph","text":"Но даже ужасаться нельзя бесконечно — голод вновь напомнил о себе. Не хотелось есть всухомятку, и уж тем более запивать еду холодной водой. Кирилл потянулся к котелку, чтобы снова поставить его кипятиться, но обнаружил его опрокинутым набок. Тяжело вздохнув, он отправился к озеру, вооружившись фонариком."},{"kind":"paragraph","text":"Возвращаясь, он заметил у костра фигуру."},{"kind":"paragraph","text":"«Ну хорошо, очнулась», — с облегчением подумал Кирилл."},{"kind":"paragraph","text":"Он уже заготовил речь, которая бы объяснила незнакомке, как она здесь оказалась, и вопросы, которые объяснили бы то же самое ему. Но на границе света и тепла, распространяемого огнём, стояла не девушка, а дедушка в потёртом пальтишке, опиравшийся на длинную палку."},{"kind":"paragraph","text":"— Да ты не боись! — для убедительности дед растянул морщинистые губы в приветливой улыбке. — Я не разбойник какой, в моём возрасте чужого уже ничего и не надо. Своего не растерять бы, и то ладно… Мне бы согреться только, что-то совсем промёрзли косточки. Можно у костра твоего погреться?"},{"kind":"paragraph","text":"— Конечно… можно… — опешив, пробормотал Кирилл. — Грейтесь…"},{"kind":"paragraph","text":"— Вот спасибо, вот хорошо… — надтреснутым старческим голосом забормотал дедок, придвигаясь осторожно к огню и устраиваясь поудобнее. Странно, но удобным он счёл присесть на корточки, распахнуть полы пальто и, по-лягушачьи растопырив коленки, протянуть руки почти в пламя."},{"kind":"paragraph","text":"При свете огня стало возможным разглядеть гостя получше. Дедушка был уже в таком возрасте, когда невозможно определить, сколько ему лет, — предположив любую похожую на правду цифру, смело можно было бы прибавить или убавить лет двадцать, и всё бы показалось правильным ответом. Его седая борода была подстрижена так неаккуратно, как если бы он сам её обрезáл тупой ножовкой, а из-под тяжёлых бровей выглядывали старчески влажные голубые глаза, оттенком напоминавшие голубовато-белёсый мутный болотный лёд."},{"kind":"paragraph","text":"— И как вы, дедушка, здесь оказались в такое-то время? — завёл Кирилл светский разговор, установив котелок так, чтобы он и нагревался, и не опрокидывался."},{"kind":"paragraph","text":"— Я, вишь, домой иду, вот и оказался! А время — что мне время, — отмахнулся старик добродушно. — Пока бессонница, знай иди себе, пока идётся, а как не идётся — так и отдыхай."},{"kind":"paragraph","text":"— И далеко вы живёте? — поинтересовался Кирилл, расслабившись от успокаивающе журчавшей речи."},{"kind":"paragraph","text":"— Да тут недалече, ногам дело привычное, — ответил старик весело. — Вот посижу да пойду, а как пойду — считай, и пришёл. А сам-то ты куда и откуда?"},{"kind":"paragraph","text":"— Я так, отдыхаю. Турист, неместный. Сюда на электричке, тут покататься, а потом опять на электричку, — он не стал слишком вдаваться в подробности."},{"kind":"paragraph","text":"Старик, покивав, тоже не стал ничего уточнять, только пробубнил что-то вроде: «Агась, агась», — и замер, спрятав водянистые глаза за кустами бровей."},{"kind":"paragraph","text":"Посидели немного молча, глядя в мерно потрескивающий огонь. Наконец вода вскипела. Кирилл всыпал в неё чаю и сахару, достал банку рыбных консервов."},{"kind":"paragraph","text":"— Угощайтесь, дедушка! — предложил он гостю. — Кружка-то есть у вас?"},{"kind":"paragraph","text":"— Вот спасибо, это хорошо бы… — дед, словно только того и ждал, извлёк из-за пазухи глиняную кружку и протянул Кириллу прямо через костёр, как будто вообще не чувствуя поднимавшегося жара."},{"kind":"paragraph","text":"Кирилл наполнил кружку чаем так быстро, как только мог, чтобы этот старикашка не поджарил свою руку."},{"kind":"paragraph","text":"— Печенье будете? Халву? Рыбу?"},{"kind":"paragraph","text":"— Рыбу-то? — дедушка рассмеялся хриплым и немного булькающим смехом. — Нет, это уж нет, спасибо. Вот сладкое, это да, уважь старика, угости… — Он снова протянул свою огнеупорную руку с обломанными грязными ногтями. — А дева-то юная что ж? — спросил он, получив порцию."},{"kind":"paragraph","text":"— Дева-то... — Кирилл запнулся и вместо того, чтобы рассказать о пугающих обстоятельствах встречи с этой самой «девой», почему-то решил темнить. — Она не будет, устала."},{"kind":"paragraph","text":"— Уста-а-ала, значит?.. Ага-а-ась… — протянул дед, и Кириллу показалось, что его взгляд на мгновение стал молодым и неприятно-цепким. — А что она? Попутчица, подруга? Невеста?.."},{"kind":"paragraph","text":"— Ну-у-у… Она… Девушка моя… — ответил он, решив, что если уж врать, то до конца."},{"kind":"paragraph","text":"— Твоя, значит? — дед елейно улыбнулся и, ненадолго перестав жевать и прихлёбывать, бросил насмешливый, как показалось Кириллу, взгляд на единственный велосипед. — Ну, совет вам, как говорится… да… Да, в мои-то времена таких понятий не было. Подруга — значит, подруга, невеста — так уж невеста… А девушка — это любая дева незамужняя… Ну что ж, времена меняются, и порядки тоже! Сколько традиций было и праздников, а вот, все забываются. И даже несложно блюсти, казалось бы… Вот, положим, раз в десять лет обряд какой дедовский справить... Так нет, не до того, забывается… всё забывается… Ох, засиделся я тут с тобой что-то! Спасибо тебе за приют и угощение, да вот, видишь, пора мне. Прощай, путник, дорога тебе скатертью! Заходи ещё в наши места при случае…"},{"kind":"paragraph","text":"Старик поднялся на удивление ловко, неуловимым шулерским движением запрятал опустевшую кружку в недра своих карманов и лёгкой походкой двинулся прочь, почти мгновенно растворившись во тьме."},{"kind":"paragraph","text":"«Странный всё-таки дедок», — подумал Кирилл и почувствовал, что с уходом этого ночного визитёра словно морок какой-то прошёл, и от сердца отступила смутная тяжесть."},{"kind":"paragraph","text":"Он проверил, как там его новообретённая спутница. Результат осмотра его обнадёжил: её лицо порозовело, губы из синеватых стали почти красными, а дыхание — ровным и глубоким. Она больше не выглядела как труп или коматозница — просто мирно спящая девушка, пригревшаяся в спальнике возле костра."},{"kind":"paragraph","text":"После столь долгого дня Кирилла тоже клонило в сон, да вот только непонятно было, где найти себе место, да и выпитый чай очень уж явственно просился на выход. Наконец, устав от этой борьбы, он поднялся и отошёл от огня на расстояние, требуемое приличиями. Влажный холодный ночной воздух взбодрил и сбросил остатки тягуче-тревожного впечатления, оставшегося после визита старика с посохом."},{"kind":"paragraph","text":"Вернувшись к огню, Кирилл застал ещё одного гостя, но на этот раз ещё более неожиданного и страшного."},{"kind":"paragraph","text":"Нисколько не смущаясь горящего костра, лохматый бурый медведь стоял, склонив голову к спальному мешку, и с явным интересом обнюхивал его содержимое. Кирилла он, очевидно, не видел. Ещё можно было тихонько отступить под прикрытие ночи и, не привлекая внимания к себе, подождать, пока всё кончится…"},{"kind":"paragraph","text":"«Да что же, сука, за день-то такой?!» — успел подумать он, но больше подумать ничего уже не успел."},{"kind":"paragraph","text":"Вместо размышлений он подскочил к костру, схватил палку, подцепил ей горящие дрова и метнул их в зверя. Медведь рявкнул и дёрнулся, но, вместо того чтобы броситься наутёк, вскочил на задние лапы и обрушился, подмяв под себя несостоявшегося героя."},{"kind":"paragraph","text":"Умереть Кирилл толком не успел — он проснулся. Нетронутый костёр всё так же отбрасывал вокруг красные блики, а незнакомка в его спальнике всё так же уютно посапывала, совершенно самостоятельно переворачиваясь с боку на бок. Окончательно придя в себя, он лёг рядом со своей назва́ной девушкой, спасая её от холода, а себя — от мистического страха. Но до утра уже больше не спал."},{"kind":"paragraph","text":"* * *"},{"kind":"paragraph","text":"Девушка открыла глаза, и по её взгляду было ясно, что она не понимает, где находится, да и вообще мало что понимает. Она начала судорожно пытаться выбраться из спальника, но безуспешно. Кирилл ей помог — и вовремя. Как только она освободилась, её вырвало, и продолжало тошнить всё утро."},{"kind":"paragraph","text":"Она была слаба и говорила с трудом, вспомнить хоть что-нибудь о себе ей не удавалось — даже имя, хоть она и мучительно старалась. Чтобы как-то к ней обращаться, Кирилл начал называть её Аней."},{"kind":"paragraph","text":"Путь к цивилизации при таком раскладе занял два дня, и оба дождь шёл, уже не прекращаясь, не встречалось на дороге ни единой живой души. Еды катастрофически не хватало, но, к счастью, страдал лишь сам Кирилл — у его спутницы не было никакого аппетита, и большую часть пути она шла, как во сне."},{"kind":"paragraph","text":"В долгожданном посёлке удалось купить еды и невольно узнать о последних местных новостях: буквально вчера где-то тут, по соседству, дождями и талыми водами размыло дамбу и смыло среди ночи бо́льшую часть посёлка. Сообщение об этом оставило неприятный осадок, но глубоко переживать о судьбе неизвестных людей не получалось — эта новость практически ничем не отличалась от тех, что ежедневно льются на голову со всех площадок."},{"kind":"paragraph","text":"— Ну что, Анечка, пошли в полицию сдаваться! — бодрясь, отрапортовал Кирилл, после того как с пищей было покончено. За время, вынужденно проведённое рядом, он исподволь привязался к своей новой знакомой. Жаль было осознавать, что теперь их пути должны разойтись."},{"kind":"paragraph","text":"Девушка смущённо пожала плечами и неопределённо улыбнулась. Даже в его одежде, явно ей слишком просторной, в его шлёпках и шапке она была очень милой."},{"kind":"paragraph","text":"Опорный пункт их встретил тишиной и запустением. Только дежурная у входа остановила нелюбезным:"},{"kind":"paragraph","text":"— Вы куда? Никого нету, все на устранении ЧС. Срочное у вас?"},{"kind":"paragraph","text":"Пока молодые люди осмысливали вопрос, зазвонил телефон."},{"kind":"paragraph","text":"— Слушаю, — вежливо и почти ласково ответила она в трубку переменившимся голосом."},{"kind":"paragraph","text":"Её разговор занял минут десять. К концу беседы во дворе припарковался уазик."},{"kind":"paragraph","text":"Аня, внимательно и тревожно посмотрев в окно, побледнела и срывающимся голосом прошептала Кириллу на ухо:"},{"kind":"paragraph","text":"— Я… вспомнила… кое-что… бежим… Бежим!"},{"kind":"paragraph","text":"— Так что там у вас?! — остановил их женский голос, снова ставший властным."},{"kind":"paragraph","text":"Кирилл схватил дёрнувшуюся к выходу Аню под руку, предостерегая от глупости."},{"kind":"paragraph","text":"— Ничего срочного, — ответил он непринуждённо. — У друга велик тут спи… украли, то есть! Мы позже заглянем, а то сейчас у вас и так, я смотрю, дел полно…"},{"kind":"paragraph","text":"Под удивлённым пристальным взглядом дежурной они покинули помещение и прошли мимо служебного внедорожника, возле которого задумчиво курил, встав в кружок, весь его экипаж."},{"kind":"paragraph","text":"* * *"},{"kind":"paragraph","text":"Аня успокоилась только в электричке. Билеты на всякий случай взяли в другую сторону — с тем, чтобы потом пересесть на автобус. По дороге она задремала, доверчиво положив голову Кириллу на плечо."},{"kind":"paragraph","text":"Аккуратно, чтобы не разбудить её, он достал телефон и открыл чат с несостоявшимися попутчиками."},{"kind":"paragraph","text":"Сообщения вроде: «Ну и пошёл ты, мудила!» ― постепенно сменились тревожными вопросами, как у него дела, и жив ли он вообще."},{"kind":"paragraph","text":"«Глянь, жесть какая. Ты ведь там где-то? Такое, как ты, не тонет, но… давай там аккуратней, что ли. Отпишись, как сеть будет!» — гласило последнее сообщение от Макса."},{"kind":"paragraph","text":"В прикреплённой видюшке был репортаж о том самом посёлке, только вчера погибшем где-то рядом. Похоже, больше всего оператору понравился кадр, на котором он задержался особо: течение медленно тащит прочь большую чёрную машину, украшенную цветами и лентами."},{"kind":"paragraph","text":"«Не ссыте, ребзя, всё шикардос! Огнище погодка! Решил подольше отдохнуть от вас», — написал Кирилл в чат, чувствуя, как мурашки медленно ползут вверх по спине."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
