INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-elop',
  'Ёлоп',
  (SELECT id FROM "Authors" WHERE name = 'Юрий Кузин' ORDER BY id LIMIT 1),
  'mrd5/mrd5-elop.jpg',
  'data:image/jpeg;base64,',
  1600,
  923,
  'Я взглянул на часы — массивный командирский хронометр, болтавшийся на моём узком запястье. Я купил его у Гошки, соседа по парте, разбив копилку о дверной косяк. Целый час мы выстраивали полки́ из медяков, а кроме денег я',
  '[{"kind":"image","path":"mrd5/mrd5-elop.jpg","caption":"Иллюстрация Екатерины Апенько"},{"kind":"paragraph","text":"Я взглянул на часы — массивный командирский хронометр, болтавшийся на моём узком запястье. Я купил его у Гошки, соседа по парте, разбив копилку о дверной косяк. Целый час мы выстраивали полки́ из медяков, а кроме денег я отдал приятелю ещё и альбом с марками, ведь часы, как оказалось, ещё и светились в темноте."},{"kind":"paragraph","text":"— Хочешь секрет? — загнал меня Гошка в кладовую и, погасив ночник, поднёс «командирские» циферблатом к моим глазам. — Гляди, как горят!"},{"kind":"paragraph","text":"— Ага…"},{"kind":"paragraph","text":"— А почему, знаешь?"},{"kind":"paragraph","text":"— Батарейки?"},{"kind":"paragraph","text":"— Балда… Плавники это удильщика глубоководного… Их в Марианской впадине по пальцам пересчитать."},{"kind":"paragraph","text":"— Подумаешь, — скривился я, прикидывая, во что мне обойдётся эта вещица."},{"kind":"paragraph","text":"Но то было год назад. А сегодня я был полноправным хозяином «луковицы» — водостойкой, небьющейся, с надписью «Заказ МО СССР» на циферблате."},{"kind":"paragraph","text":"Стрелки указывали на пять утра."},{"kind":"paragraph","text":"Тихо, как вор, я стянул шорты со спинки стула и, натягивая их, пританцовывая на одной ноге, подошёл к окну."},{"kind":"paragraph","text":"Утро теплилось, но даже в этой грохочущей синеве я увидел, как пляшет моя грудь, — впалая, как у дистрофика, — и в ужасе подумал: «А что, если я умру? Что, если и сердечко моё вот так же пустится в бега?»"},{"kind":"paragraph","text":"Холод половиц обжёг пятки, и я подумал, что было бы глупо простудиться в такой день. Но больше, чем свалиться с температурой, я боялся, что мысль о «драконе» выскользнет из моей головы и покатится по комнате, гремя и подпрыгивая, как пятак. Я знал, что трезвон разбудит мать и что, заспанная, неумытая, со свалявшимися волосами, она обрушит на мою стриженую голову свою натруженную руку. Вот тогда всё коту под хвост. Вот тогда-то душа моя и предстанет перед её суровым взором ворохом наспех сшитых страниц. Всё, что я впишу в этот блокнот, все мои каракули мать расшифрует и пронумерует. Она прочтёт меня от корки до корки. Она узнает всё о побеге, который я затеял, и о доме в тени старых лип, куда цыгане привезут «дракона» этим майским утром и где меня напрасно будут поджидать грузчики. Я знал, что, если мать посадит меня под замок, пяткам моим не сверкать у дома тётушки, когда «змия» станут поднимать лебёдками на второй этаж. И тогда пиши пропало, тогда мне не увидеть, как чумазые, полусонные грузчики, чертыхаясь и пыхтя цигарками, зажатыми между кривыми и редкими зубами щербатого рта, впихнут «трёхлапого» в окно, не услышать проклятий, которыми «лежебока» станет сыпать при каждой царапине на его смоляной, как воронье перо, чешуе."},{"kind":"paragraph","text":"Я топтался у двери ни жив ни мёртв, боясь, что мысль, обронённая мной, разбудит квартал. Но мать даже не пошевелилась, когда, взобравшись на табурет, я стянул с гвоздика ключ и вставил бороздкой в замочную скважину."},{"kind":"paragraph","text":"В шесть я выбежал из дома. А без четверти семь «КамАЗ» с «рептилией» нагнал меня у ворот парка, куда я юркнул, чтобы срезать путь."},{"kind":"paragraph","text":"Мы двигались ноздря в ноздрю. Но то ли от недосыпа (всю ночь я таращился на часы), то ли от немощи (весной губы мои покрывались авитаминозными корками, ресницы спутывала дрёма, а фантазия пускалась во все тяжкие), очутившись в медвежьем углу парка, я впал в ступор. Я не знал, метаться ли в поисках выхода или упасть ничком на чёрную, пахнущую перегноем клумбу, пока бодрый милицейский пёс не уткнётся холодным шершавым носом в моё бледно-землистое лицо. Страх стреножил волю, но и придал сил. Я стал плутать. А когда, озябший, с разбитыми в кровь коленками, я очутился у особняка, взятого под стражу голыми, почерневшими за зиму липами, хвост ящера уже торчал из двери балкона, как вымазанный в чернике язык, которым гигант, казалось, дразнил меня за нерасторопность."},{"kind":"paragraph","text":"Подойдя к дому, я заревел — громко, протяжно, точно баржа, севшая на мель."},{"kind":"paragraph","text":"— Юрка! Ты, что ли?"},{"kind":"paragraph","text":"Я увидел на балконе силуэт тёти Шуры, обрамлённый слепящим светом, а спустя минуту, полногрудая, сияющая, она возвышалась над моим карликовым тельцем."},{"kind":"paragraph","text":"— Уже внесли? — спросил я сквозь слёзы."},{"kind":"paragraph","text":"— Уже, — ответила она. — Такой нам тут цирк устроил, проказник, что и не передать!"},{"kind":"paragraph","text":"Тут тётушка крепко обняла меня, всхлипывающего и шмыгающего носом, и я почувствовал жар от её плеч, квадратных и сутулых, какие бывают только у пловчих, бравших золото в юности."},{"kind":"paragraph","text":"— Ну довольно, хватит! — с упрёком сказала она. — Мне тут расплатиться нужно. Рабочие ждут. А ты дуй-ка к мамке. А вечером приходите. На смотрины. Я такую кулебяку испеку!"},{"kind":"paragraph","text":"Я с недоверием уставился на неё. Тётушка улыбнулась, а затем насупилась, но не взаправду, а понарошку."},{"kind":"paragraph","text":"— Ну так ждать тебя на пирог или нет? — спросила она сухо, выждав паузу."},{"kind":"paragraph","text":"— Ждать. — Я кивнул."},{"kind":"paragraph","text":"Домой я летел как на крыльях. А домчавшись, выложил всё как есть матери. И про «КамАЗ». И про «трёхлапого». И про смотрины."},{"kind":"paragraph","text":"Мать слушала молча, нервно вздыхая при каждой подробности, которыми я расцвечивал свой рассказ. К полудню она вся извелась. А в три, несмотря на обеденный час, мы стали ломиться к тётушке. Дубовую дверь, обтянутую алой кожей, обитую медными гвоздиками, с узким, как книжный обрез, окошечком для газет и журналов открыли не сразу. Без парика и перстней, сжимавших её убитые артритом пальцы, сестра матери была похожа на осыпавшуюся ёлку, порыжевшую, с обрывками конфетти, которую воткнули в мартовский сугроб. Закрыв на цепочку дверь, тётка попеняла матери за «набег», который уж точно сократит жизнь каждому, ведь хуже, чем внезапный визит, может быть только смерть — вот уж кому плевать на приличия. Нам позволили войти в столовую, где за обеденным столом, облепив его, как осы головку мёда, сидели нахмурившись дядя Рубен и три мои кузины."},{"kind":"paragraph","text":"Покончив с супом, я выбежал из-за стола. «Гад» томился в гостиной. Я вошёл. Я хотел лишь приголубить эту «тварь»."},{"kind":"paragraph","text":"Дверь распахнула Женька: «Стейнвей» был куплен ей. Впрок куплен, чтобы завидовали."},{"kind":"paragraph","text":"В белом платьице, с алыми бантами в косичках, наглячка преградила мне путь к роялю. А потом буркнула:"},{"kind":"paragraph","text":"— Чул, не лапать!"},{"kind":"paragraph","text":"Прижимистость была их семейной чертой. Обычно меня выдворяли из всех шести комнат, чтобы уберечь от праздного любопытства, к которому, как считалось, я был склонен. И верно, я во всё совал свой нос. Но интерес мой к миру был философским. Я познавал мiр на ощупь. Я клал мiр на зуб, а распробовав, терял интерес к его терпкому ядрышку. Вот и сейчас, войдя в гостиную, я лишь хотел почувствовать кожей музыку — а зачем ещё, спрашивается, нужны клавиши, как не для пальцев, на кончиках которых мелодия вьёт гнёзда и даже выводит птенцов?"},{"kind":"paragraph","text":"Я сделал шаг к роялю."},{"kind":"paragraph","text":"— Стой! — Женька вперила в меня взгляд, острый, как коготок птички, которым охотница выковыривает личинок из-под коры дуба. — Ты куда это соблался?"},{"kind":"paragraph","text":"— Туда. — Я выкинул вперёд руку, как Наполеон, взирающий на Москву с Воробьёвых гор."},{"kind":"paragraph","text":"— Глупый ты, Юлка! — Наглячка топнула, да так громко, что в чешском серванте задребезжал фаянсовый сервиз. — А есё — дулак!"},{"kind":"paragraph","text":"— Это почему же?"},{"kind":"paragraph","text":"— Да потому! — Разбойница ткнула меня пальчиком, да так яростно, точно хотела проделать во мне дыру. — И вообсе, — продолжила: — сколо тебя в интелнат сдадут. Для силоток. Там питание тлёхлазовое. И лезым..."},{"kind":"paragraph","text":"Она упёрла ручки в бока."},{"kind":"paragraph","text":"— Не «лезым», а режим, — поправил я сестрицу. — Только врёшь ты всё, Женька."},{"kind":"paragraph","text":"— А вот и не влу! — Тут сорока прильнула своими влажными, пахнущими карамелью губками к моему зардевшемуся уху и произнесла заговорщицким тоном: — Мамка твоя муза себе подыскивает. Непьюсего. А ты месаес."},{"kind":"paragraph","text":"Дверь с шумом распахнулась. Мы обернулись. На пороге, скрестив на груди руки, стояли обе наши мамаши. Загорелая, поджарая, как прогорклый корж, — тётушка. Пухленькая, рябая, как булочка с кунжутом, — мать."},{"kind":"paragraph","text":"— Ну-ка, мелочь, — тётушка отвесила подзатыльник дочери, — марш на кухню тарелки мыть!"},{"kind":"paragraph","text":"— Нет уж, пусть договорит, — возразила мать. — Хочу послушать, чему ты, сестра, учишь племянницу."},{"kind":"paragraph","text":"— Прекрати, Варвара! — Тётушка зажала плачущей Женьке рот, чтобы та не сболтнула лишнего."},{"kind":"paragraph","text":"— И верно, пора уж прекратить. — Мать схватила меня под локоть и поволокла в коридор. — Ноги моей больше не будет в доме, где сплошные сплетни!"},{"kind":"paragraph","text":"Она наспех одела меня, долго искала носки, но, не найдя, вывела меня из дома в сандалиях на босу ногу."},{"kind":"paragraph","text":"— Взбалмошная! — Тётушка швырнула нам с балкона носки. Но мать тащила меня за руку не оглядываясь, точно буксир, снявший баржу с мелководья."},{"kind":"paragraph","text":"Месяц мы не общались. Мать ждала извинений. Но телефон молчал. Мать даже отнесла его в мастерскую в надежде вправить вывихнутый сустав или наложить шину на сломанную кость, виновницу семейных склок. Но тётушка, похоже, и не собиралась названивать. Так прошёл ещё месяц. А к концу третьего бодрая, розовощёкая мать внесла в нашу узкую, как пенал, комнатку продолговатый футляр."},{"kind":"paragraph","text":"— Вот, держи. — Она открыла ящичек, обтянутый дерматином, достала из чёрной бархатки скрипочку и протянула мне. — Концерты давать будешь. По радио. А там, глядишь, и в телевизор пригласят. Хочешь, Юрка, в телевизор?"},{"kind":"paragraph","text":"Тут мать рухнула в соломенное кресло — жёсткое, обтянутое белым чехлом — и сказала, смахнув слезу:"},{"kind":"paragraph","text":"— Ведь для чего-то же я рожала тебя в муках!"},{"kind":"paragraph","text":"С «мук», собственно, всё и началось. Мои беды, я хотел сказать. Ведь школа, куда определила меня родительница, ютилась в каком-то цеху, и очень скоро в раздевалку, где я стоял у пюпитра, стали наведываться литейщики в просаленных бушлатах и с цигарками в зубах."},{"kind":"paragraph","text":"Мрачный и сырой, с окнами, забранными решётками, класс напоминал камеру инквизиции, в которую нас, первоклашек, на Пасху водили учителя."},{"kind":"paragraph","text":"Два раза в неделю я спускался в этот «ад», где меня «поджаривали на сковороде, поливая маслом до хрустящей корочки»."},{"kind":"paragraph","text":"Пытку поручили буковинцу с крепкими, как щипцы, пальцами. Бес говорил тихо и размеренно, и лишь вспышки ярости, дремавшие в фалдах его безупречно сшитого концертного костюма, вспарывали его безупречную русскую речь — так гвоздики не вбитые, а лишь насаженные, прорывают гробовой креп."},{"kind":"paragraph","text":"Только заслышав голос тирана, высокий, как милицейский свисток, я терял дар речи. Казалось, только этого он и добивался. Ведь войдя в раж, почувствовав власть над трепещущей душой, деспот бил смычком по моим ладоням, а потом называл ёлопом, что на львовском диалекте означало «болван»."},{"kind":"paragraph","text":"А чтобы тупость моя была очевидна и для матери, палач велел мне вызубрить «Концерт» Ридинга, который и стал моей плахой на два ближайших года. И в самом деле, всякий раз, приходя на экзекуцию, я лишался части собственного «я», как приговорённый к четвертованию — руки или ноги."},{"kind":"paragraph","text":"Я лез из кожи вон, чтобы угодить мучителю: часами простаивал у пюпитра, пел ноты как пономарь и даже скособочился (левое плечо выше, правое ниже), но скрипка, похоже, лишь смеялась в моих руках. К тому же Ридинг, о чём падший дух говорил, ядовито улыбаясь, только и делал, что «переворачивался в гробу», и мне даже стало казаться, что дух композитора вот-вот восстанет из ада, — а куда ещё, думал я, попадают мучители детей, как не в самое пекло?!"},{"kind":"paragraph","text":"Я был жалок. Я таял на глазах. И однажды, ужаснувшись, мать просто выцыганила меня у Носатого, чтобы привести к Виртуозу, который «уж точно знал, как развить слух»."},{"kind":"paragraph","text":"Это был высокий русский в твидовом пальто и широкополой шляпе, с длинными, как у Паганини, пальцами. Одет щёголь был с иголочки, ходил циркульным шагом и поминутно заглядывал в мои глаза, точно отыскивая в них искру Божью."},{"kind":"paragraph","text":"Но Бог, похоже, слепил меня из муки грубого помола, в которую не кладут серебряных монет и которую не присыпают сахарной пудрой. К тому же узкие, как у мурзы, щёлки моих глаз покрывала поволока, сотканная из горя и неприкаянности. Скрипку я ненавидел люто. А ещё я верил, что Бог, которого нет и которого выдумали, наверняка протянет мне руку, — стоит лишь попросить."},{"kind":"paragraph","text":"Случай не заставил себя ждать. Предстоял концерт, на котором решался вопрос о моём переводе в следующий класс. Начал я с того, что не вступил, когда, сыграв «увертюру», пианист с копной седых, как у Листа, волос тупо уставился на меня. Он повторил зачин, кивая мне каждый такт, точно протезист, вложивший костыли в мои слабеющие руки. Я вступил, но пока добирался до середины пьесы, раз десять сфальшивил, взяв на полтона ниже там, где следовало взять выше."},{"kind":"paragraph","text":"Казалось, я должен был сгореть от стыда, но не тут-то было. С каким-то дьявольским удовольствием я провёл целым смычком там, где требовалась половина, сыграл вместо восьмушек шестнадцатые, бемолям предпочёл диезы и вообще — камня на камне не оставил от мелодии. Я был в ударе. Ноты срывались с моего смычка, как перезрелые забродившие сливы. О, что тут началось! Зал загудел, как потревоженный улей. А один сердобольный старичок, вскочив, предложил «прервать детоубийство» — ведь нельзя же, в самом деле, наслаждаться муками ребёнка! Этот аргумент, однако, лишь раззадорил меня. Я почувствовал власть над публикой. Я ощущал себя матадором с мулетой в руке. Я вонзал шпагу в бьющееся сердце Ридинга, не оставляя его концерту ни единого шанса. Я ликовал. И было отчего: наконец-то я взмылил лошадку по имени Месть, то пуская её галопом, то рысью, то иноходью. Куражась, я выискивал глазами Виртуоза, чтобы прочесть на его каменном лице ужас, который и должен был, по моему замыслу, послужить мне ключом к свободе. Я узнал учителя по рукам. Он сидел в последнем ряду, залепив лицо длинными, как у Паганини, пальцами."},{"kind":"paragraph","text":"Издав предсмертный хрип, музыка умерла. В ту же секунду публика разом выдохнула, точно пассажиры автобуса, увернувшегося от грузовика."},{"kind":"paragraph","text":"Первым вскочил Виртуоз. Отлепив от лица пальцы, точно сбросив с головы осьминога, он решительно подошёл к моей матери и, сложив молитвенно ладони, заикаясь, потребовал «перестать му… учить музыку!». «Да и ребёнка, — добавил он, вскинув указующий перст, — не мешало бы по… ожалеть!»"},{"kind":"paragraph","text":"Мать уменьшалась на глазах с каждым его напутствием, и казалось, ещё минута — и она растворится. Но, выплеснув всё, что у него накипело, выговорившись, Виртуоз сбежал."},{"kind":"paragraph","text":"Домой мы возвращались молча. А войдя в комнатушку, так же молча, не поужинав, легли спать. Утром, всплакнув, мать отправилась в школу, чтобы забрать документы. Я молча смотрел ей вслед. Бедная, несчастная Ма! Я хотел даже зареветь, чтобы не чувствовать себя уж слишком счастливым и чтобы никто не догадался, на какие хитрости я пустился, чтобы вернуть отобранное детство. Но слёзы упрямились. Слёзы не желали выкатываться. А вот сердечко моё звенело. И было отчего звенеть… Я не должен был больше зубрить урок, разбираться в легато и стаккато, пиликать назло родне, получая горсть мелочи в награду. А ещё я перестал чувствовать боль в пальцах, изрезанных струнами. Но главное — я был избавлен от муштры! Навсегда! Навеки!"},{"kind":"paragraph","text":"Этим всё бы и закончилось, если бы не одно «но». Утерев нос скрипке, заткнув музыку за пояс, я стал тосковать по своим обидчицам. Да, представьте! Я испытывал фантомные боли, как солдат, вернувшийся с войны без обеих ног. Правда, сегодня, спустя годы я не склонен себя оправдывать. Я был своеволен, заносчив и не любил музыку — не любил и не знал. Не знал, что за приязнь, которую к ней питаешь, музыка не сулит ни наград, ни воздаяния, ни мзды — ничего, что могло бы утешить. Музыка безответна — вот что так мучает нас и повергает в уныние. И если искусство что и бросает нам, как кость, так это крохи, которые гении забыли смахнуть со стола. Но я был слишком голоден, чтобы хранить их долго. И крошки, оставленные кем-то на столе, всегда собирал в кулачок, чтобы сунуть в рот."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
