INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-zaholustev-spasaet-rossiyu',
  'Захолустьев спасает Россию',
  (SELECT id FROM "Authors" WHERE name = 'Николай Старообрядцев' ORDER BY id LIMIT 1),
  'mrd5/mrd5-zaholustev-spasaet-rossiyu.jpg',
  'data:image/jpeg;base64,',
  1600,
  1334,
  'Захолустьев сидел на табуретке посреди комнаты и кричал. Он испускал долгий протяжный крик, напрягая все мышцы и вкладывая все силы духа, потом замолкал, закрывал глаза, немного переводил дыхание, делал глубокий вдох и с',
  '[{"kind":"image","path":"mrd5/mrd5-zaholustev-spasaet-rossiyu.jpg","caption":"Иллюстрация Лены Солнцевой"},{"kind":"paragraph","text":"Захолустьев сидел на табуретке посреди комнаты и кричал. Он испускал долгий протяжный крик, напрягая все мышцы и вкладывая все силы духа, потом замолкал, закрывал глаза, немного переводил дыхание, делал глубокий вдох и снова кричал. Это продолжалось уже минут десять."},{"kind":"paragraph","text":"Открылась дверь, и в комнату вошла мать Захолустьева."},{"kind":"paragraph","text":"— И чего ты опять кричишь? — спросила она сына голосом недовольным, но совершенно спокойным. — Ты же знаешь, что на меня эти крики никак не действуют. Ты бы лучше на улицу шёл кричать. Глядишь, какая-нибудь девушка обратила бы на тебя внимание. Сейчас любят эксцентриков. Может, и ты бы сгодился кому."},{"kind":"paragraph","text":"Не обращая на мать внимания, Захолустьев снова закричал. Покричав ещё минут пять, он встал и начал одеваться. Он надел чёрные семейные трусы, белую майку, чёрные хлопчатобумажные носки, синие кальсоны, потом серые шерстяные носки, синие джинсы, красную спортивную кофту на молнии, тёмно-серую зимнюю куртку на синтепоне, шерстяную вязаную шапочку красного цвета с белой помпошкой на шнурке. После этого он лёг на диван, засунул руки в карманы куртки и закрыл глаза."},{"kind":"paragraph","text":"На диване не было ни подушек, ни постельного белья, отчего приятнее всего было лежать просто на спине, спокойно вытянувшись. В таком положении Захолустьев умел лежать часами, не засыпая, но и не думая ни о чём. Это искусство далось ему не сразу. Ушли годы, прежде чем он отыскал все необходимые внешние компоненты и смог интуитивно нащупать внутри себя требуемые психологические механизмы."},{"kind":"paragraph","text":"Не успел он пролежать и нескольких минут, как кто-то тронул его за ногу. Захолустьев не стал открывать глаз. Он решил, что это мать бесшумно вошла в комнату и теперь испытывает его терпение. Но Захолустьев был хозяином своего терпения, поэтому таким потрагиванием за голень его было не пронять. Он продолжил лежать как ни в чём не бывало, однако его снова побеспокоили — на этот раз кто-то тряс его за плечо."},{"kind":"paragraph","text":"«Это интересная задача, — решил Захолустьев. — Если мать ведёт себя подобным образом, значит, что-то стряслось. Возможно, я умер, но этого не заметил. Поэтому мне показалось, что прошло несколько минут, а на самом деле прошло много часов, и теперь она проверяет, жив ли я. Что же я должен делать?»"},{"kind":"paragraph","text":"«Если я умер, — рассуждал он далее, уже целиком отдавшись ментальной стихии, — тогда мне ничего делать не надо, поскольку я уже мёртв и всё равно сделать ничего не смогу, даже если захочу. Следовательно, можно лежать дальше»."},{"kind":"paragraph","text":"«Если же я не умер, — настала очередь антитезиса, — тогда прошло не так много времени, чтобы нужно было по-настоящему беспокоиться, а не испытывать моё терпение. Следовательно, реагировать на прикосновение было бы против моих принципов, и я должен продолжать моё лежание, как и в первом случае»."},{"kind":"paragraph","text":"Только он успел успокоить себя этим умозаключением, как кто-то дал ему такую крепкую пощёчину, что глаза открылись сами собой, не спрашивая совета у разума."},{"kind":"paragraph","text":"Рядом с диваном бесцеремонно стояли двое. Оба в длинных бежевых плащах. Один — мужчина лет сорока, высокого роста, худощавого сложения, с коротко стриженными русыми волосами, уже тронутыми сединой, но с рыжеватой бородой и такими же усами. На носу — очки с толстыми линзами в массивной оправе из полупрозрачного пластика."},{"kind":"paragraph","text":"Второй — уже совсем старик, но весьма красивый: ясные голубые глаза, густые седые брови, тонкий костистый нос, очень высокий лоб, визуально увеличенный за счёт гладкой лысины, простирающейся до самого затылка, и длинные, белоснежные волосы, обрамляющие крупный череп по бокам и чуть касающиеся плеч."},{"kind":"paragraph","text":"— Дорогой друг, — торжественно произнёс старик, обнажив зубные протезы превосходного качества, — позвольте представиться. Меня зовут профессор Гниловский, Борис Леонидович, а это мой ассистент и биограф — писатель Николай Старообрядцев."},{"kind":"paragraph","text":"Писатель вежливо поклонился и сделал небольшое пояснение касательно своей персоны:"},{"kind":"paragraph","text":"— Я приставлен к профессору, чтобы описать всё, что он делает, и дать этому литературную обработку. Но так как это дело несложное, я также понемногу ассистирую профессору в его научной работе, стараясь при этом не привлекать к себе внимания."},{"kind":"paragraph","text":"— Именно так! — кинулся пояснять профессор. — Вы думаете, это лишнее? Я имею в виду описание. Да, и я так думал. Я просто люблю работать и считаю долгом делать свою работу безупречно. Мирская слава мне не нужна. Я не тщеславен. Даже не честолюбив. Нет! Мне совершенно не до этого! Наука для меня — альфа и омега. И что я получил? Теперь у нас говорят: «Профессор Гниловский решает проблемы, которых не существует». Казалось бы, какая мне разница? Ан нет, голубчик. Денег на исследования — ноль! Путёвки на конференции — шиш! Лабораторию вот-вот закроют. Что прикажете делать? Вот я и пошёл в Союз писателей, попросил, чтобы ко мне приставили надёжного человека. Слава богу, связи остались ещё. Иначе никак!"},{"kind":"paragraph","text":"Писатель Старообрядцев смиренно склонил голову, желая продемонстрировать, что понимает и скромность своей роли, и ответственность своей задачи. После он достал из внутреннего кармана пиджака платок и передал его профессору. Тот утёр платком капли пота, выступившие от волнения на его величественном старческом лбу. Писатель убрал платок и достал из бокового кармана плаща рабочий блокнот в кожаном переплёте. Затем он щёлкнул авторучкой и приготовился записывать."},{"kind":"paragraph","text":"— Я понял, — процедил Захолустьев, а писатель невозмутимо зафиксировал сказанное. — Это мой сон."},{"kind":"paragraph","text":"Писатель прекратил писать и посмотрел на профессора. Гниловский усмехнулся и сочувственно посмотрел на Захолустьева:"},{"kind":"paragraph","text":"— Не хотелось бы этого говорить, но при вашем образе жизни это неудивительно. Всякая сложная деловая активность, всякое серьёзное мероприятие, требующее собранности и ответственных решений, расценивается как наваждение или кошмарный сон. Но здесь, молодой человек, — профессор взглянул на Захолустьева как врач на пациента, не следующего медицинским предписаниям, — я не смогу вам подыграть. Вы не спите, а мы вам не снимся. Мы вполне реальны и пришли к вам, поскольку у нас есть к вам вполне реальное дело. Так ведь, Николай? — Гниловский обратился к Старообрядцеву, который уже успел присесть на табуретку и вовсю работал авторучкой."},{"kind":"paragraph","text":"— Даже не знаю, Борис Леонидович, — как-то кисло отреагировал писатель. — Мне-то всё это понятно. Я знаю, что я есть. Как учили нас на философском факультете: cogito ergo sum[19]. Но способны ли эти доводы переубедить человека, которому удобнее считать, что он спит и видит сон?"},{"kind":"paragraph","text":"— Да, друг мой, — всплеснул руками профессор. — Некоторые люди полагают, что вся наша жизнь — это сон. И часто даже не наш, а какого-то постороннего существа — то ли китайской стрекозы, то ли языческого божка, задремавшего на полянке после любовных утех со своими наложницами. Но даже если это так, то всё равно есть некий сон, в котором вы, мой дорогой, — профессор переключился на Захолустьева, — обнаруживаете себя намного чаще, чем в любом другом сне. И в этом сне вы обладаете очень показательной привычкой просыпаться, а потом снова ложиться спать. Некоторые пытливые умы также заметили, что в этом сне законы физики действуют с какой-то назойливой постоянностью, чего не скажешь о других, обрывочных и ускользающих снах, в которые вы погружаетесь каждую ночь. Если, конечно, вы не страдаете бессонницей, как я. Впрочем, я уже утомил вас этими банальностями."},{"kind":"paragraph","text":"Но это было не так. Захолустьев нисколько не утомился. Если лежать в тишине с закрытыми глазами, не имея мыслей, он научился только недавно, то делать то же самое, но с открытыми глазами и при посторонних, которые разговаривают, он умел всегда."},{"kind":"paragraph","text":"— К счастью, — торжественно поднял палец профессор, — есть один простой приём, который приняли на вооружение даже те люди, которые в силу патологических нарушений работы мозга постоянно путают сон и явь. Нужно просто подойти к выключателю на стене и нажать на клавишу. Видите ли, спящий мозг не учитывает законы электротехники и скрытую проводку, а потому не может смоделировать правильную работу даже простейшего бытового выключателя. Николай! — он обратился к писателю. — Помогите нам, пожалуйста, разрубить этот гордиев узел."},{"kind":"paragraph","text":"Старообрядцев встал с табуретки, прошёл ко входу в комнату и нажал на клавишу выключателя. Ничего не произошло."},{"kind":"paragraph","text":"Профессор наморщился, как будто ему наступили на ногу, но быстро преодолел замешательство:"},{"kind":"paragraph","text":"— Николай, записывайте, — после чего продиктовал: — Всё это ему снилось. Точка. Записали? Теперь покажите нам запись, а я попытаюсь объяснить нашему юному другу, как трудно воспринимать письменный текст в ситуации сновидения, особенно человеку, который редко общается с рукописными источниками, — Гниловский бросил какой-то быстрый иронический взгляд в сторону Захолустьева."},{"kind":"paragraph","text":"— Позвольте, я сначала проверю лампочку, — возразил писатель. — Она могла просто перегореть."},{"kind":"paragraph","text":"Сказав это, он пододвинул табуретку под абажур, встал на неё и дотянулся до лампы. Захолустьев заметил, что писатель ходит по его комнате в уличной обуви: на его ногах были новенькие летние ботинки из чёрной кожи. Почти такие же, но с какими-то старомодными медными бляхами, были на ногах профессора, который расхаживал по комнате, нисколько не стесняясь. Грязи на полу он не оставлял, но всё же Захолустьев зашевелился на своём ложе от недовольства. Заметив это, профессор присел к нему на диван:"},{"kind":"paragraph","text":"— Так-с, наконец-то мы оживаем, — он игриво подмигнул Захолустьеву и принял из рук Старообрядцева лампочку, которая к тому моменту уже была выкручена."},{"kind":"paragraph","text":"— Итак, коллеги, — профессор поднял лампочку, немного отстраняя от себя, как делают дальнозоркие старики. — Что же мы видим? Классическая лампа накаливания мощностью семьдесят пять ватт. Обратите внимание на вольфрамовую нить. Вы видите? Она надорвана. Вот здесь. Это означает только одно: лампа перегорела. Я вас поздравляю, Николай, — профессор обратился к писателю с деланым ликованием. — Ваша гипотеза оказалась верна. Вам же, коллега, — он снова переключился на Захолустьева, — я должен выразить свои соболезнования. Теперь вы никогда не узнаете, спите вы или нет, не говоря уж об элементарном освещении этой комнатушки... Впрочем, если у вас есть запасная лампочка, — новая надежда осветила лицо старого профессора, — мы с Николаем могли бы заменить её, убив двух зайцев разом."},{"kind":"paragraph","text":"— У меня нет лампочки, — несколько раздражённо ответил Захолустьев. — Но если я не сплю, то где моя мать? Почему она вас пустила?"},{"kind":"paragraph","text":"— Допустим, мы пока не решили, спите вы или нет, — захихикал профессор. — Но что спит ваша мать, это я вам могу гарантировать. Спит крепко и сладко."},{"kind":"paragraph","text":"Он сложил ладони вместе и подставил их под ухо, закрыв глаза и показывая тем самым сладко спящего человека. Поглядев на профессора как на безумца, Захолустьев обратился взглядом к Старообрядцеву. Тот уже успел снова сесть на табуретку и совершенно спокойно, закинув ногу на ногу и покачивая ботинком, ответил:"},{"kind":"paragraph","text":"— Мы её усыпили. Дали снотворное."},{"kind":"paragraph","text":"— Какое снотворное? — полюбопытствовал Захолустьев."},{"kind":"paragraph","text":"Писатель перевернул несколько страниц своего блокнота, возвращаясь к началу, и зачитал:"},{"kind":"paragraph","text":"— Циклобарбитал. Триста миллиграммов."},{"kind":"paragraph","text":"— Проверенный рецепт! — заметил профессор. — Рекомендую. Если будет нужно, помогу достать. Связи ещё остались, слава богу."},{"kind":"paragraph","text":"— Зачем вы это сделали? — прямо поинтересовался Захолустьев, не обращая внимания на фармакологические посулы профессора."},{"kind":"paragraph","text":"— Видите ли, друг мой, — поспешил ответить Гниловский, — о нашем пребывании здесь никто не должен знать. От этого напрямую зависит качество выполнения работы. Как я уже сказал, моя работа должна быть безупречна, и единственным её свидетельством станет литературный отчёт нашего дорогого Николая."},{"kind":"paragraph","text":"Старообрядцев всё это время неотрывно вёл конспект."},{"kind":"paragraph","text":"— Что это за работа? — всё более настораживался Захолустьев."},{"kind":"paragraph","text":"— Об этом я вам сказать не могу, — мягко улыбнулся Гниловский. — По крайней мере не здесь. Вам нужно будет пойти с нами, и со временем я расскажу все детали предстоящей нам операции."},{"kind":"paragraph","text":"— Вы врач? — вдруг подозрительно глянул Захолустьев."},{"kind":"paragraph","text":"— Вовсе нет! — тихонько засмеялся профессор. — Это вы про операцию? Не беспокойтесь, никто вас оперировать не будет. По крайней мере, — он весело подмигнул Захолустьеву, — если сами об этом не попросите."},{"kind":"paragraph","text":"Захолустьев хотел опять что-то спросить, но профессор перебил его:"},{"kind":"paragraph","text":"— Вот что, друг мой! У меня только что возникла идея. Надеюсь, она сэкономит нам время, а потом мы обязательно обо всём договоримся. Вот смотрите. Мы до сих пор так и не смогли вам доказать, что вы не спите. Может, это и к лучшему? Считайте, что спите, и делайте то, о чём вас просят. Ведь что бы ни случилось, с вас взятки гладки. Стало быть, нет смысла упрямиться, не так ли? Если же это не сон, то просто присмотритесь к нам повнимательнее. Мы люди серьёзные, это же сразу видно. Посмотрите ещё раз на меня, — Гниловский приосанился и очень выразительно глянул на Захолустьева. — Посмотрите на Николая."},{"kind":"paragraph","text":"Старообрядцев оторвался от своей работы и тоже с самым серьёзным выражением посмотрел на Захолустьева через свои очки."},{"kind":"paragraph","text":"— Разве мы похожи на мошенников?"},{"kind":"paragraph","text":"— Нет, — согласился Захолустьев. Ему понравилась аргументация профессора."},{"kind":"paragraph","text":"На лестничной клетке Захолустьев вдруг заметался и рванулся было назад в квартиру."},{"kind":"paragraph","text":"— Что такое? — Профессор преградил ему путь."},{"kind":"paragraph","text":"— Обувь забыл."},{"kind":"paragraph","text":"— Николай! — быстро обратился Гниловский к писателю. — Не в службу, а в дружбу!"},{"kind":"paragraph","text":"Старообрядцев открыл дверь, чтобы вернуться в квартиру."},{"kind":"paragraph","text":"— Красные полусапожки, болоньевые, — сказал ему вослед Захолустьев."},{"kind":"paragraph","text":"Наконец, после долгой возни, его обули. Сам бы он справился быстрее, но профессор всё норовил позаботиться о нём, что только досаждало и вносило лишнюю суету. Полусапожки оказались очень практичной обувью. Благодаря тонкой подошве из современного полимерного материала в них было очень удобно и легко ходить. Увидев, как мягко Захолустьев ступает по асфальтированной дорожке, профессор пришёл в неподдельный восторг."},{"kind":"paragraph","text":"— Николай! — потребовал он. — Обязательно опишите эту обувь. Только в такой и буду ходить, когда кончатся все эти хлопоты! Впрочем, что это я лезу не в своё дело? Пишите, как считаете нужным. В этом деле я вам полностью доверяю."},{"kind":"paragraph","text":"— Спасибо, профессор! — поблагодарил Старообрядцев. Даже на ходу, едва поспевая за Гниловским и Захолустьевым, он успевал делать пометки в блокнот."},{"kind":"paragraph","text":"— Вам не жарко, друг мой? — профессор осмотрел наряд Захолустьева, не очень шедший к летнему сезону."},{"kind":"paragraph","text":"Захолустьев ответил каким-то бессмысленным взглядом, но это только дополнительно воодушевило профессора:"},{"kind":"paragraph","text":"— Очень вас понимаю! Я бы и сам так ходил. Уютнее как-то. Да и косточки уже мёрзнут в мои-то годы. Но проклятое общественное положение, — профессор гневно распахнул свой фирменный плащ, демонстрируя элегантнейший двубортный костюм из чёрной шерсти в тонкую белую полоску, сшитый на заказ в дорогом ателье. — Приходится пускать плебеям пыль в глаза, чтобы можно было хотя бы приоткрыть рот на их глупых бараньих заседаниях."},{"kind":"paragraph","text":"Минут через десять они достигли станции метро."},{"kind":"paragraph","text":"— Как вы уже догадались, — с ноткой скорби в голосе Гниловский обратился к Захолустьеву, — служебной машины у меня нет. Отобрали! Но, — он гордо поднял голову, — в данном случае обстоятельства работают на нас. В метро у них нет жучков. Кроме того, кое-какие деньги мне ещё выделяют, так что сегодня прокатимся за мой счёт. Вперёд, джентльмены. А точнее — вниз!"},{"kind":"paragraph","text":"— Итак, друг мой, — профессор приблизился вплотную к Захолустьеву, когда они спускались на эскалаторе, — мне не терпится перейти к делу. Вы, должно быть, думали, что дела никакого и нет. «Старый дурак морочит мне голову!» Так ведь вы думали? На вашем месте я бы думал именно так."},{"kind":"paragraph","text":"Захолустьев так вовсе не думал. Он давно уже знал, что если не думать, то всё происходит само собой — зачастую лучше и интереснее, чем когда обдумаешь и взвесишь каждый шаг. Даже в толкотне метро под напором слов незнакомца ему удавалось почти не думать. Он просто слушал, что ему говорят. Гниловский продолжал:"},{"kind":"paragraph","text":"— Должно быть, вы не раз уже слышали, что Россию надо спасать?"},{"kind":"paragraph","text":"Захолустьев воспринял этот вопрос без всякого энтузиазма. Но профессору как будто было всё равно:"},{"kind":"paragraph","text":"— И это правда, голубчик! Россию давно пора спасать. «От кого?» — спросите вы. И вовсе нет, — почти безумно расхохотался профессор, будто услышал предположение Захолустьева, хотя тот продолжал молчать. — Вовсе не от евреев, мой неистовый юный друг! Сейчас у России куда более опасный противник!"},{"kind":"paragraph","text":"Они вошли в вагон. Гниловский зажал Захолустьева в угол, подальше от посторонних ушей. Старообрядцев изо всех сил льнул к ним, чтобы не пропустить ни слова. Он уже знал в общих чертах, о чём будет говорить профессор, но тут было важно ухватить интонации — ему нужен был живой материал, а не теоретические выкладки."},{"kind":"paragraph","text":"— Главного врага России зовут Антипапа Лжедмитрий, — Гниловский перешёл к самой сути дела. — Я не уверен, что это человек, поэтому правильнее будет называть его существом. Тёмной сущностью, если хотите. Он очень сильный маг и телепат. Говоря более популярным языком, экстрасенс. С помощью своих сверхъестественных способностей он уже много лет воздействует на членов правительства России, заставляя их принимать неправильные решения. Мне удалось вычислить, где находится его логовище."},{"kind":"paragraph","text":"Сказав это, профессор устремил на Захолустьева сверкающий огненный взгляд. Но тому было не особенно интересно, где прячется главный враг России. Не то чтобы он был человек нелюбопытный или равнодушный к судьбам своей страны. Нет, он тоже чем-то интересовался. Он даже думал иногда, что он патриот. Но за последнее время в нём поселился какой-то душевный холод, который сам подсказывал ему ответы на такие вопросы. И если бы Захолустьев спросил себя, где кроется истинный враг России, этот холод ответил бы ему просто:"},{"kind":"paragraph","text":"— Везде."},{"kind":"paragraph","text":"Если бы Захолустьев на этом не успокоился и попросил бы дать более конкретный ответ, душевный холод не заставил бы себя ждать:"},{"kind":"paragraph","text":"— В твоём сердце. Ты и есть главный враг России."},{"kind":"paragraph","text":"Захолустьеву такие ответы не нравились, поэтому он научился не думать и месяцами напролёт почивал на своём диване, созерцая пустоту."},{"kind":"paragraph","text":"— В могиле Сталина! — победоносно изрёк профессор."},{"kind":"paragraph","text":"Бедный старик не понимал, какой собеседник ему достался. А ведь он был не глуп. Это был один из умнейших людей на планете, и такие, как Захолустьев, были ему плохо известны просто потому, что наука не занимается пустотой такого рода. Науке известен вакуум, но это пустота совершенно иная. Вакуум может быть чрезвычайно полезен в хозяйстве. Что же касается Захолустьевской пустоты, то рядом с ней всё приходило в упадок и лишалось значения. Может быть, учёный всё это понимал, но отважно отыгрывал свою роль, чтобы давать достойный материал перу писателя, который неотступно следовал за ним и записывал каждый его шаг и каждое слово."},{"kind":"paragraph","text":"— И можете мне поверить, — в голосе профессора зазвучала нотка восхищения, — он оборудовал там себе прекрасное гнёздышко! Это сверхсовременный, абсолютно неприступный бункер, оснащённый всеми благами цивилизации. У нашего дорогого существа там есть всё, чего душа ни пожелает, вплоть до соковыжималки. Если душа у него всё-таки имеется, в чём я очень сомневаюсь."},{"kind":"paragraph","text":"— Даже соковыжималка есть? — заинтересовался вдруг Захолустьев, чем привёл профессора в неописуемый восторг. — Откуда вы знаете?"},{"kind":"paragraph","text":"— Несомненно! — вскричал Гниловский уже с такой экспрессией, что на него начали озираться пассажиры вагона. — Я готов спорить на все свои научные регалии, что соковыжималка у него имеется. У меня чутьё на такие вещи!"},{"kind":"paragraph","text":"Тут поезд остановился, и это привело профессора в чувство. Увидев на табло название станции, он вскинул брови, крепко схватил Захолустьева и потащил его к выходу:"},{"kind":"paragraph","text":"— Наша станция! Немедленно покинуть вагон."},{"kind":"paragraph","text":"На эскалаторе профессор особенно плотно приобнял Захолустьева:"},{"kind":"paragraph","text":"— Друг мой! Как я уже сказал, бункер Антипапы Лжедмитрия абсолютно неприступен. Единственный способ нейтрализовать злодея — выманить его наружу. Для этой-то цели я и решил обратиться к вам. Ведь вы, голубчик, не только патриот своей страны, но вообще человек экстраординарный."},{"kind":"paragraph","text":"Захолустьев и тут не удивился. Он хорошо знал о своих экстраординарных способностях. Их развитию он посвятил всю свою жизнь. Он понял, что сегодня пробил его звёздный час. Он сможет обучить членов правительства России полностью останавливать мышление, тогда злобному телепату нечем будет манипулировать, да и элементарные человеческие ошибки перестанут вкрадываться в ход государственного механизма, и тогда наконец-то жизнь в России наладится сама собою. Россия будет спасена."},{"kind":"paragraph","text":"Только одного не мог понять Захолустьев. И чтобы не думать самому, спросил:"},{"kind":"paragraph","text":"— Как вы меня нашли?"},{"kind":"paragraph","text":"Они уже вышли из метро и шли кратчайшим путём в сторону Красной площади."},{"kind":"paragraph","text":"— Как же, дорогой мой? — Непонимающе уставился на него профессор. — Мы с самого утра вместе с Николаем ходили по городу. Я надиктовывал варианты, но понимал, что всё это не пойдёт. И уже был близок к отчаянью. Казалось, что до обеда ничего путного не придумать. Как вдруг мы услышали ваши вопли. Это было просто божественно! Вы сами позвали нас. То есть меня. Извините, Николай! — бросил Гниловский писателю. Он иногда забывал, что писатель не должен обозначать своё присутствие во всей этой истории. Он должен просто фиксировать факты, а потом их художественно оформлять, поворачивая нужной стороной."},{"kind":"paragraph","text":"Захолустьеву было глубоко плевать на все эти тонкости. Его беспокоило другое. Он иначе воспринимал свою роль в спасении России и сейчас корил себя за чрезмерно разгулявшуюся фантазию. Больше всего его угнетало то, что пока он лежал на своём диване, как бревно, без единой мысли в голове, где-то внутри, в какой-то неизведанной полости, тлела самолюбивая надежда, и вот теперь она целиком обнажилась перед ним во всём своём бездумном и наглом уродстве. Захолустьев так расстроился, что повернулся, чтобы уйти прочь. Но не тут-то было. Они как раз остановились чуть левее Мавзолея, прямо напротив могилы Сталина. Профессор резким движением одёрнул Захолустьева, ловко развернул его лицом к могиле и приказал:"},{"kind":"paragraph","text":"— Кричи!"},{"kind":"paragraph","text":"— Нет, — воспротивился Захолустьев и снова было дёрнулся назад, но тут произошло что-то совсем скандальное. Гниловский снова одёрнул его ещё сильнее, неожиданно влепил крепкую пощёчину и заорал прямо в лицо, не дав опомниться:"},{"kind":"paragraph","text":"— Кричи, я сказал, собака! Спасай Россию!"},{"kind":"paragraph","text":"Захолустьева закружило. Им сразу овладели и бешеная ярость, и обжигающая обида, и острейшее чувство несправедливости. Он никогда ещё не переживал такого унижения. Его оскорбляли на Красной площади, прямо на могиле Сталина, перед лицом всей России. Он почувствовал, что слёзы вот-вот брызнут из глаз, и закричал — так же пронзительно, как утром этого дня."},{"kind":"paragraph","text":"К ним со всех сторон стали стекаться люди. Впереди всех бежал человек в форме полицейского. Его лицо было перекошено от злобы, а рука уже лежала на кобуре. Профессор крепко ухватил Захолустьева под руку и приказал:"},{"kind":"paragraph","text":"— Бежим! Быстро!"},{"kind":"paragraph","text":"Они побежали. Старообрядцев же, который всё это время стоял немного поодаль, быстрым шагом отошёл в сторону и смешался с толпой. Ему важно было услышать мнение масс и сделать несколько небольших, но точных штрихов. Такие вещи всегда очень выгодно смотрятся в произведении."},{"kind":"paragraph","text":"Профессор и Захолустьев спрятались под аркой ГУМа. Гниловский постоянно высовывался из-за колонны и пристально вглядывался в происходящее на площади. Между делом он как мог подбадривал Захолустьева, который совсем расклеился и во всём своём одеянии стал похож на какую-то груду тряпья:"},{"kind":"paragraph","text":"— Тихо! Потерпи немного! Он сейчас покажется."},{"kind":"paragraph","text":"Вдруг профессор указал пальцем вдаль и каким-то сдавленным, но грозным голосом гаркнул:"},{"kind":"paragraph","text":"— Вон он! За ним. Ату его! Ату!"},{"kind":"paragraph","text":"Он опять схватил Захолустьева и потащил обратно на площадь. Никто уже не обращал на них внимания. Даже полицейский, ещё недавно готовый пристрелить нарушителей порядка, покинул свой пост и отбыл в кордегардию справлять какие-то свои полицейские нужды."},{"kind":"paragraph","text":"Захолустьев не понимал, за кем они гонятся. Впереди были только люди. Равнодушные волны человеческой массы. Он не мог поверить, что средь них крадётся великая тёмная сущность, долгие годы сидевшая под землёй, чтобы истязать беззащитное тело России."},{"kind":"paragraph","text":"Но вот толпа поредела, они выбежали на Ильинку. Теперь Захолустьев уже догадывался, что они преследуют человека невысокого роста в военной форме. Он видел только спину. Заметил он также, что их нагнал Старообрядцев. Писатель шёл немного сбоку, чтобы не влезать в основную канву повествования, и опять прямо на ходу делал пометки в блокноте."},{"kind":"paragraph","text":"Они оказались на улице поменьше. Она была пустынной, но довольно узкой, так что Старообрядцеву пришлось идти прямо за ними, отставая всего на несколько шагов. Человек в форме исчез. Захолустьеву показалось, что они его потеряли. Но профессор не унимался:"},{"kind":"paragraph","text":"— Он где-то здесь! Я чувствую эту тварь!"},{"kind":"paragraph","text":"Они дошли до поворота на Безымянный переулок. Захолустьев повернул голову и остолбенел. Переулок был перегорожен строительными конструкциями, образуя слепой мешок. Там, в этом тупике, стоял Иосиф Виссарионович Сталин. Генералиссимус курил свою знаменитую трубку."},{"kind":"paragraph","text":"У Захолустьева потемнело в глазах. Ноги его стали подгибаться. Но профессор, уже весь запыхавшийся и еле живой от этой гонки, не утратил присутствия духа. Он сильно ущипнул Захолустьева и тут же закричал на Сталина:"},{"kind":"paragraph","text":"— Попался! Долго же я тебя выслеживал!"},{"kind":"paragraph","text":"На лице Сталина было написано полное недоумение. Вынув трубку изо рта, он только и успел оправдаться:"},{"kind":"paragraph","text":"— Я не Сталин!"},{"kind":"paragraph","text":"— Ага! Вот ты и сознался, — взревел профессор, — Антипапа Лжедмитрий!"},{"kind":"paragraph","text":"Растерянно оглядев троих собравшихся, человек, выглядевший как Сталин, но говоривший, что он не Сталин, продолжил давать уклончивые ответы:"},{"kind":"paragraph","text":"— Товарищи! Я здесь уже восьмой год работаю. Кому-то нравится, что я Сталин, кому-то нет, всякое бывало, но вы вообще какие-то глупости говорите."},{"kind":"paragraph","text":"Теперь уже и Захолустьеву стало понятно, как выгодно было этой твари иметь облик Сталина. Если бы кто-то нагрянул в могилу с неожиданной проверкой, он бы увидел там ровно то, что должен был увидеть, — нетленное тело отца народов."},{"kind":"paragraph","text":"Не желая вступать в прения со столь хитроумным существом, профессор раскрыл полы плаща, расстегнул пиджак и вытащил из нательной кобуры пистолет. Это было на редкость устрашающее орудие с блестящим удлинённым стволом, немного утолщающимся на конце."},{"kind":"paragraph","text":"— Не стреляйте, — поднял руки Сталин, выронив от страха трубку. — Я пенсионер. Ветеран труда."},{"kind":"paragraph","text":"— Заткнись, тварь, — рявкнул профессор и протянул пистолет Захолустьеву. — Твоя песенка спета. Попил ты кровушки русской!"},{"kind":"paragraph","text":"Но Захолустьев и не думал брать пистолет. Ему опротивел весь этот фарс."},{"kind":"paragraph","text":"— Бери! — истерически заорал на него Гниловский, весь покраснев от напряжения. — Такого шанса больше не будет."},{"kind":"paragraph","text":"Захолустьев попятился назад. На этот раз он не отказался думать, и мысль, родившаяся первой в его голове, не была успокоительной: «Профессор Гниловский — опасный сумасшедший»."},{"kind":"paragraph","text":"Воспользовавшись замешательством в рядах борцов с абсолютным злом, таинственный субъект, одновременно бывший и не бывший Сталиным, развернулся, в несколько шагов добежал до строительных конструкций и полез наверх, желая перелезть на другую сторону. Операция оказалась под угрозой срыва. Профессор направил пистолет на Захолустьева, видимо, желая расстрелять того на месте за измену родине. Но тут к ним подоспел Николай Старообрядцев. Он встал перед профессором, заслоняя собой Захолустьева, потом, улучив момент, ловко выхватил из руки Гниловского пистолет, взвёл его и выстрелил в человека, заползавшего на конструкции."},{"kind":"paragraph","text":"Тело рухнуло вниз. Старообрядцев подошёл к нему и сделал ещё два выстрела — в грудь и в голову. После этого он вернулся к Захолустьеву и протянул ему оружие. Тот стоял как вкопанный. Руки безвольно свисали по бокам."},{"kind":"paragraph","text":"— Подержи, пока я записываю, — потребовал Старообрядцев."},{"kind":"paragraph","text":"Захолустьев протянул руку и взял пистолет."},{"kind":"paragraph","text":"— Записывайте, Николай, — Захолустьев услышал довольный голос профессора, который диктовал писателю текст: — Захолустьев убил Антипапу Лжедмитрия. Точка. Он спас Россию. Точка."},{"kind":"paragraph","text":"Осознав, что Старообрядцев его подставил, Захолустьев, отдавшись порыву ненависти, поднял руку с пистолетом, навёл её на писателя и спустил курок."},{"kind":"paragraph","text":"Когда звук выстрела смолк, Захолустьев открыл глаза. Профессор Гниловский очень деликатно извлёк из его руки пистолет и убрал к себе в кобуру. Писатель Старообрядцев стоял тут же, совершенно невредимый."},{"kind":"paragraph","text":"— Промах! — профессор похлопал Захолустьева по плечу. — Ещё миллиметр правее, и пришлось бы мне давать взятку, чтобы в Союзе писателей согласились дописать эту историю с моих слов."},{"kind":"paragraph","text":"— Как опишем этот забавный инцидент, Николай? — Улыбнулся Гниловский писателю. — Ведь вас здесь нет."},{"kind":"paragraph","text":"Старообрядцев пожал плечами в недоумении."},{"kind":"paragraph","text":"— Хорошо! — воскликнул профессор. Победа вдохновила его. — Записывайте. Наслаждаясь смертью врага, Захолустьев не сдержался и выстрелил в воздух."},{"kind":"paragraph","text":"Когда труп был наскоро прикрыт валявшимся тут же строительным мусором, профессор вызвал такси. Захолустьева отвезли домой и уложили обратно на диван. Мать всё ещё спала."},{"kind":"paragraph","text":"Вечером приходили следователь и участковый. Следователь интересовался, покидал ли Захолустьев квартиру. Мать ответила, что он не выходил уже несколько месяцев. Тогда следователь полюбопытствовал, почему Захолустьев лежит в уличной одежде. Мать объяснила, что он всегда так делает. Участковый подтвердил показания матери. Он знал, что за птица этот Захолустьев. Он давно уже наблюдал за ним, потому что соседи жаловались на его крики по утрам. После этого хранители правопорядка ушли. Ушла и мать. Прикрывая дверь в комнату сына, она обратила внимание, что он лежал в своих красных полусапожках, хотя раньше не надевал их. Но она решила не придавать значения этому факту. Материнское сердце чувствовало, что сын всё делает правильно."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
