INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-pechalnaya-istoriya',
  'Печальная история',
  (SELECT id FROM "Authors" WHERE name = 'Пётр Беликов' ORDER BY id LIMIT 1),
  'mrd5/mrd5-pechalnaya-istoriya.jpg',
  'data:image/jpeg;base64,',
  1600,
  1366,
  'В подвале одной из хрущёвок на северной окраине Санкт-Петербурга спала длинная тощая крыса. Свет фонаря едва проникал через вентиляционное отверстие и освещал горы мусора: грязный картон, прогнившие доски, куски битого к',
  '[{"kind":"image","path":"mrd5/mrd5-pechalnaya-istoriya.jpg","caption":"Иллюстрация Лены Солнцевой"},{"kind":"paragraph","text":"В подвале одной из хрущёвок на северной окраине Санкт-Петербурга спала длинная тощая крыса. Свет фонаря едва проникал через вентиляционное отверстие и освещал горы мусора: грязный картон, прогнившие доски, куски битого кирпича, старые журналы и газеты, разодранные и частично отсыревшие. Свернувшаяся клубком крыса укуталась в несколько слоёв ветоши. Рядом с ней лежало её чтение — кусок газеты «Правда» за 1981 год. В газете писали о ядерной угрозе, нависшей над СССР стараниями стран НАТО. Крыса собрала вокруг себя и прочие милые сердцу приметы Советского Союза. Себе под голову она подложила спичечный коробок с изображением локомотива и развевающегося над ним знамени «ПЛАНЫ ПАРТИИ — ВЫПОЛНИМ!». Вокруг лежали и другие спичечные коробки. Так, на одном из них был нарисован Сталинградский тракторный завод с надписью «50 ЛЕТ ПЕРВОЙ ПЯТИЛЕТКЕ». На другом — изображён электровоз с подписью «ПЕРВЫЙ СОВЕТСКИЙ ЭЛЕКТРОВОЗ 1932». Именно внутри этого коробка хранилась главная реликвия крысы — украденный у бабушки, распродававшей свои вещи, значок октябрёнка."},{"kind":"paragraph","text":"Подъём с постели крысе, уже не первый год мучающейся от химической зависимости, давался непросто. Хотелось укутаться в эту ветошь и вовсе не вставать — так и лежать в этом подвале на окраине жизни. Но такой роскоши она позволить себе не могла. Каждое утро её мучила тревога. Звуки, доносившиеся с улицы и от соседей, били по нервам."},{"kind":"paragraph","text":"С первого этажа стала доноситься песня:"},{"kind":"paragraph","text":"— Пролетели года, отгремели бои."},{"kind":"paragraph","text":"Отболели тяжёлые раны твои,"},{"kind":"paragraph","text":"Но, далёкому мужеству верность храня,"},{"kind":"paragraph","text":"Ты стоишь и молчишь у Святого огня."},{"kind":"paragraph","text":"Собрав весь свой запас сил, крыса покинула подвал хрущёвки через вентиляционную дыру и оказалась в лабиринте пятиэтажек, который тут и там освещался фонарями. С моря насквозь продувал ледяной ветер, как будто прорезавший шерсть крысы лезвием ножа. Крысу окружали хрущёвки. Между домами выстроились скелеты деревьев, уже значительно выросшие с шестидесятых годов, когда их только посадили. Пространство было поделено между тропинками для пешеходов, проездами для машин, огороженными участками, где летом была трава (сейчас они просто были завалены снегом со следами мочи), домами, некоторые окна в которых уже были убраны разноцветными гирляндами, и припаркованными автомобилями, у которых иногда загорался свет фар. В этом свете неторопливо опадали снежинки, создавая ощущение замедленного времени. Возле разноцветных «кремлей» детских площадок резвились дети."},{"kind":"paragraph","text":"В этих местах, неподалёку от своего дома, крыса искала наркотики, что было сопряжено для неё со множеством опасностей. В памяти крысы всплывали картины того, как разогнанный солями мужчина в спортивном костюме нёсся за ней по дворам с отломленной корягой, стремясь переломить хребет грызуна. Промахиваясь, мужчина наносил удары по сугробам, отчего комья снега взлетали в пустоту ночи. К счастью, в ту ночь крысе удалось забиться под палатку шавермы, откуда мужчина уже не смог её достать, как он ни орудовал своей корягой."},{"kind":"paragraph","text":"Стоило попытать счастья в одной парадной, в которой на подоконнике стоял цветок. Именно в земле этого цветка часто можно было найти «клад»."},{"kind":"paragraph","text":"Крыса добралась до необходимой парадной и, спрятавшись под скамейкой, стала ждать, когда кто-нибудь выйдет или зайдёт. На отходах ощущалось, что нервы из-под кожи вытащены наружу. Любой окрик во дворе, проезжающая машина или гудок заставляли дёргаться всё тело крысы. Сознание пожирала тревога. В итоге крысе начало казаться, что из-за возможного взрыва газовой колонки подвал со всей её советской коллекцией окажется разрушен. Кроме того, реликвии крысы могли похитить бомжи. Затем крысе представилось, как её повесили на этом огромном тополе посреди советского двора вместе со множеством других крыс. Она знала, что люди относились к таким существам, как она, со смесью страха и брезгливости, а любовь к чтению дала крысе представление об исторических практиках человека (пусть и извращённых в её сознании). Ей представилось, как свисающие с высохших ветвей крысы раскачиваются на ветру. В итоге мёртвыми крысами оказались увешаны все деревья северной части города. В это время года крысу от полного морального упадка спасал, как это ни странно, снег. Своим благородным холодным одеялом он прикрывал серость и грязь этих бесконечных дворов."},{"kind":"paragraph","text":"Наконец дверь парадной с пиликаньем открылась и из неё вышла мама с коляской, а за ней, по всей видимости, отец семейства в необъятном пуховике и с мусорным пакетом. Крыса, оставшись незамеченной, успела проскочить в закрывающуюся дверь и нырнуть в тёплое кирпичное нутро дома, прогретое центральным отоплением. На оборотной стороне двери, ведущей в парадную, скотчем был приклеен листок с надписью:"},{"kind":"paragraph","text":"«Уважаемые соседи! Убедительная просьба: не открывайте двери незнакомцам. В нашем подъезде стали прятать наркотики»."},{"kind":"paragraph","text":"Подоконник с цветком располагался после второго лестничного пролёта. Уже подобравшись к горшку, крыса ощутила разочарование. В сбившейся комьями земле явно кто-то успел порыться. Решив всё же попытать удачу, крыса принялась глубже закапываться в землю, в итоге совсем забравшись в цветочный горшок. Поняв тщетность своих попыток отыскать наркотик, крыса принялась выбираться из горшка. После того как она облокотилась передними лапами на одну стенку, горшок потерял равновесие и с треском рухнул на плитку. По полу разлетелись комья земли, керамические куски разбившегося горшка, а чахлый цветок разметал свои листья по подъездной плитке. Одна из двух пенсионерок, спускавшихся в этот момент по лестнице для совершения вечернего моциона, ойкнула от неожиданности."},{"kind":"paragraph","text":"Вскочившая крыса, отряхнувшись от земли, ринулась вниз по лестничному пролёту, промчавшись между бабушек. Спрятавшись в углу холла, за одной из детских колясок, крыса стала ждать, когда бабки покинут парадную, чтобы можно было выскочить на волю вслед за ними."},{"kind":"paragraph","text":"Крыса принялась обыскивать окружающие дома, пробираясь в темноте вдоль стен пятиэтажек. В первую очередь крыса заглядывала за жестяные карнизы возле окон первых этажей, не забывая и про внутренние стены подвалов, куда человек мог протянуть руку сквозь вентиляционную дыру. Ныряла крыса и в водосточные трубы, надеясь отыскать закладку в их металлических полостях. Раз за разом её постигала неудача. Пять домов, проверенных крысой во всех местах, где могли быть заложены наркотики, оказались «пустыми». Уже отчаявшись в своём абстинентном психозе, крыса увидела вдалеке группу молодых ребят."},{"kind":"paragraph","text":"Бросалось в глаза, что один из них — высокий, худой и с длинными, покрашенными в светлый цвет волосами, спускающимися из-под капюшона, — был в компании главным. Он бегал со смартфоном вокруг нескольких деревьев, светя фонариком окрест группы деревьев и кустов. Примерно в двадцати метрах, возле такси, курили «Филип Моррис» две молодые девушки."},{"kind":"paragraph","text":"— Игорян, ну не стой на месте, твою мать! Посвети ещё вон там."},{"kind":"paragraph","text":"— Сейчас будет всё, не торопись."},{"kind":"paragraph","text":"— Если опять ненаход будет, я ебанусь просто, — говорил молодой человек явно на нервах."},{"kind":"paragraph","text":"— Вот, точно это дерево на снимке. — Игорян сначала раскопал руками снег, а потом подвернувшейся палочкой попытался расковырять промёрзшую землю."},{"kind":"paragraph","text":"— Да не здесь, вот видишь, комьями прикрыто, — нервно прикрикнул тот парень в капюшоне."},{"kind":"paragraph","text":"В этот момент притаившаяся в скелете кустов крыса ринулась к комьям земли и выхватила заветный прозрачный пакетик с белым веществом."},{"kind":"paragraph","text":"— Что-о-о? Лови её, ёб твою!.."},{"kind":"paragraph","text":"Вокруг крысы несколько раз обрушились удары тяжёлого зимнего ботинка. Не попав под удар, крыса с пакетиком в зубах успела юркнуть в ближайшую вентиляцию в хрущёвке."},{"kind":"paragraph","text":"— ДА БЛЯ-Я-Я-ЯДЬ, СУКА! Еба́ная крыса, я зарежу её, нахуй! Как мне попасть в этот подвал?!"},{"kind":"paragraph","text":"— Максим, ты не попадёшь туда! Нам придётся сейчас новую закладку смотреть."},{"kind":"paragraph","text":"— Представляете, у меня крыса спиздила соль! Реальная живая крыса, ебануться! — кричал Максим случайно проходившему мимо мужику."},{"kind":"paragraph","text":"Максим сбросил капюшон, кинулся к стене, за которой скрылась крыса, и начал с неожиданной для его телосложения силой наносить по этой стене удары ногой. Казалось, что хрущёвка заходила ходуном."},{"kind":"paragraph","text":"Игорь стал успокаивать его и отводить за плечи. Подошли девчонки."},{"kind":"paragraph","text":"— Максим, успокойся, давай хоть таблов возьмём."},{"kind":"paragraph","text":"— О, мне Лера написала сейчас, — сказала одна из девушек. — У них всё есть. Они на Ветрах, нас всех угостят."},{"kind":"paragraph","text":"— Фу-у-у-у-ух! Поехали быстрее, — выдохнул Максим."},{"kind":"paragraph","text":"Крыса, примостившись на дощечке, раскрыла лапками пакетик и аккуратно высыпала перед собой небольшую дорожку. Вдохнув в себя значительную дозу порошка, крыса почувствовала, как её постепенно стало накрывать тёплое чувство эйфории. Животное ощутило прилив энергии; жёсткая шёрстка, чёрная ближе к телу и порыжевшая на концах, приподнялась в возбуждении, а в глазах загорелся шальной демонический огонёк. Сразу захотелось двигаться. Показываться на глаза людям, чтобы они шарахались от неё в брезгливости. Бегать ночью по детской площадке, кататься с горки — прямой или винтовой. Или сходить к ларьку шавермы, который так красиво сияет в ночи своими неоновыми трубами. Отрыть в помойке неподалёку недоеденную шаверму."},{"kind":"paragraph","text":"Но для начала нужно было запрятать остаток вещества в надёжное место, а именно в спичечный коробок «ПЛАНЫ ПАРТИИ — ВЫПОЛНИМ!». И крыса, взяв пакетик в зубы, чуть не подпрыгивая от распирающей её энергии, понеслась через дворы в свой заветный уголок. Холод больше не прошибал тело — напротив, по организму разливалось тепло. Разноцветные огни машин, окон и гирлянд красиво расцвечивали темноту ночи. Тёмно-сиреневые облака на иссиня-чёрном небе драматично наплывали на полумесяц, создавая ощущение театральной декорации. А сквозь заметные тут и там маленькие дырочки на лоскуте неба просвечивал ослепительно-золотой свет. В одном из найденных в подвале журналов крыса видела, как на картинке эти небесные точечки света пунктирными линиями объединяли в «созвездия». Впрочем, самой крысе никогда не удавалось объединить их — всегда не хватало каких-то точек, скрытых не то облаками, не то тяжёлым дыханием города."},{"kind":"paragraph","text":"Буквально впрыгнув в родной подвал, крыса решила разогнаться напоследок перед сегодняшней ночью. В последнее время «отпускать» её стало рано и резко, настолько, что бывало сложно пошевелиться от внезапно накатывавшей трезвости. Была слишком велика вероятность, что вещества не хватило бы до утра. Экономно отделив себе ещё горсточку, крыса снюхала порошок со спичечного коробка."},{"kind":"paragraph","text":"Взбеленённая крыса выбежала из дворов и понеслась по широченному тротуару Ленинского проспекта. Несмотря на тщедушное тельце, из-за воздействия химических веществ от крысы исходили очень мощные энергетические вибрации, ассоциирующиеся с первобытной силой тираннозавра. Пугающий вид на обывателей производили скорость крысы, дикие глаза и вздыбленная шерсть. В это время суток по тёмной окраине в свои квартиры возвращались люди, дольше других задерживающиеся на работе. В большое общежитие на краю района шли загулявшие в центре города студенты, а многие местные жители, наоборот, выходили прогуляться с коляской, дойти до супермаркета, аптеки или пивного ларька, возле которых ещё можно было поболтать со знакомыми. Из-за плохого освещения проспекта некоторые прохожие только краем глаза успевали заметить проносящегося грызуна, а некоторым, заметившим его заранее, приходилось отпрыгивать подальше в сторону, провожая крысу матом. Пока крыса неслась во весь опор, она ощущала раскрывающееся наслаждение от отворившейся тёмной стороны её существа. Сама себе она начала казаться демоническим порождением, которое ранее было эфемерным, но теперь смогло наконец найти свою телесную оболочку. В голове проносились мысли:"},{"kind":"paragraph","text":"«Я КРЫСА ИЗ АДА!»"},{"kind":"paragraph","text":"«Я СБЕЖАЛА ПРЯМО ИЗ АДА В ЭТИ СОВЕТСКИЕ БЕТОННЫЕ КОРОБКИ!»"},{"kind":"paragraph","text":"«ЧТОБЫ ЖИТЬ, МНЕ НУЖНО ПОЖИРАТЬ СОЛЬ, КОТОРУЮ ВАРЯТ В АДУ!»"},{"kind":"paragraph","text":"Проносившись с полчаса между дворами и проспектом, распугивая прохожих, совершенно обессиленная, но летающая в волнах эйфории крыса зарылась в снег. Лёжа в снегу, который не охлаждал, а, казалось, наоборот, согревал её, крыса созерцала небесное полотно, восхищавшее своей красотой. На фоне такого драматически-мрачного неба всё происходящее внизу казалось до смешного пошлым и незначительным."},{"kind":"paragraph","text":"Отдышавшись, крыса увидела вдалеке своего знакомого, Пашу. Это был скромный парень примерно двадцати пяти лет, вечно в капюшоне и с эспаньолкой. Он направлялся на тусовку, на которой в тот день обещал быть неплохой состав «ветеранов». Именно в этот момент его догнала крыса, переваленная в снегу и с вываленным наружу языком."},{"kind":"paragraph","text":"— Здарова, крыс! А я иду к Пеймону на вписон. Затусишь с нами?"},{"kind":"paragraph","text":"Крыса, отряхиваясь от снега, мелкой трусцой побежала рядом с Пашей в дальнюю парадную."},{"kind":"paragraph","text":"— Пеймон, открывай! Я с крысом! — прокричал Паша в домофон сквозь завывавший ветер, после чего железная дверь отворилась с пиликающей мелодией."},{"kind":"paragraph","text":"Парадные в этих домах трудно было отличить одну от другой. Однако здесь уже со второго этажа слышались звуки музыки, шум и женский хохот. Внутри тесной однушки с отошедшими тут и там обоями было накурено. На советском ещё линолеуме проступали пятна пролитых когда-то, возможно, месяцы назад, алкогольных коктейлей. Навстречу Паше и крысе вышел Пеймон — что-то ехидно-злое всегда было заметно в его взгляде и сардонической улыбке. Можно было бы сказать, что это из-за не выводившихся из его крови стимуляторов, однако даже в редкие моменты трезвости его хитрый с поволокой взгляд был почти таким же. Несмотря на убитую квартиру, одет он был по всей молодёжной моде."},{"kind":"paragraph","text":"— О-о-о, я смотрю, крыс уже в деле! Как всегда, под элементами хайпа. — Пеймон любил громогласно комментировать происходящее."},{"kind":"paragraph","text":"— Да я сам обалдел, что-то он просто в мясо сегодня, — ответил Паша. — А я трезвый как стекло."},{"kind":"paragraph","text":"— Ну что, ты в деле?"},{"kind":"paragraph","text":"— Давай, только не борщи, как обычно. Я тебе на «Сбер» переведу."},{"kind":"paragraph","text":"Крыса, Пеймон и Паша из прихожей вошли в гостиную, где был ещё больший беспорядок."},{"kind":"paragraph","text":"— Привет, Лина! — Паша обнялся сначала с Линой — чуть пухлой, очень привлекательной девушкой с блестящими глазами, в чёрном платье и с ярким макияжем, а затем и с Дашей — бледной брюнеткой с чёрным каре, в серой толстовке оверсайз."},{"kind":"paragraph","text":"Крыса тем временем прыгнула на кровать ближе к Даше, забилась в угол, подобрав под себя одеяло, и, заняв удобную обзорную позицию, стала наблюдать за происходящим. Из колонок доносились танцевальные ритмы."},{"kind":"paragraph","text":"С кухни вышел шестой участник вписки — здоровый, массой больше ста килограммов парень по прозвищу Орочимару (по паспорту Иван)."},{"kind":"paragraph","text":"— Ну что, насыпать? — Орочимару просыпал на икеевский столик горстку порошка."},{"kind":"paragraph","text":"— Вань, здорово! Мне сделай дорожку, — сразу оживился Паша."},{"kind":"paragraph","text":"— И мне, а то чувствую, что я тут буду самая трезвая, — весело сказала Лина, отпивая свой пивной напиток."},{"kind":"paragraph","text":"— Смотри опять концерт не устрой во дворе, как в тот раз было, — улыбаясь, ответил Пеймон."},{"kind":"paragraph","text":"— Не ссы! Будь мужиком, блядь! — шуточно помахала кулаком Лина. — Нормально я себя контролирую."},{"kind":"paragraph","text":"— Так нормально, что ментам в прошлый раз «Стигмату» пела. Или не помнишь?"},{"kind":"paragraph","text":"— А ничего, пусть приобщаются."},{"kind":"paragraph","text":"— Тебя на наркотики проверили, кстати? — спросил занюхавший жирную дорогу Паша."},{"kind":"paragraph","text":"— Проверили: штраф четыре тысячи платить плюс административка. А всё из-за соседки ёбаной этого Толика."},{"kind":"paragraph","text":"— И так уже несёт тебя — дорожка уменьшается, значит, — отрезал Орочимару, отодвинув «сберовской» кредиткой часть порошка."},{"kind":"paragraph","text":"— Ну Орочи! — надулась Лина, но тут же занюхала всё, что ей отделили, а затем принялась потирать носик."},{"kind":"paragraph","text":"— Крысу не нужно сегодня больше, как я посмотрю? — иронически спросил Орочимару, бросив взгляд на крысу, лежавшую с перекосившейся мордой, выпавшим языком и выкатившимися глазами. Её маленькое тело сотрясало тяжёлое и гулкое дыхание."},{"kind":"paragraph","text":"— Да давайте ещё ему сыпанём — может, в себя придёт? — предложила Лина."},{"kind":"paragraph","text":"— Крыса передознулась, это пиздец! — заявил Пеймон."},{"kind":"paragraph","text":"— Это уже живодёрство называется, дорогая моя! — ответил Паша."},{"kind":"paragraph","text":"— А что ему? Наркологичку вызвать? Чтобы откачивали? — Лина залилась смехом."},{"kind":"paragraph","text":"— Можно считать это экспериментом над животным. Любые препараты ведь сперва на крысах тестируют. Кстати, что покажу! — Пеймон отлучился в ванную комнату и вернулся с длинной, как раз под размер нашего героя, ловушкой для крыс, что вызвало смех у сидящих в гостиной ребят."},{"kind":"paragraph","text":"Ловушка представляла собой клетку, внутри которой на штырь Пеймон прикрепил кусок «Российского» сыра, напоминающий много лет пролежавший в комоде пластилин. Штырь должен был приводить в действие пружину, захлопывающую дверь клетки. Что было делать с этой клеткой с рвущейся из неё крысой потом, после того, как клетка захлопнется, пользователям в инструкции к ловушке не объяснили. Добивать крысу чем-то через прутья клетки или нести её, беснующуюся и рвущуюся наружу, на помойку прямо в ней? А самые отчаянные крысоловы в наркотическом угаре наверняка готовы будут выбросить пойманную в ловушку крысу хоть с крыши девятиэтажного дома."},{"kind":"paragraph","text":"— Это я специально купил в строительном магазине. У меня ведь и так живёт крыса, только трезвенница. Шумит, сука, спать мне не даёт. А когда я на отходах, у меня сон чуткий. На неё эта ловушка впечатления не произвела: она оказалась гораздо умнее тех, кто эту ловушку сделал. Крысы ведь умные, блядь. Наш, значит, тем более не поведётся — он уже матёрый. Но пускай тут в углу постоит — узнаем его мнение, так сказать."},{"kind":"paragraph","text":"— Мне кажется, скорее создатели этой ловушки сами в неё попадутся, — засмеялась Лина, покачнувшись и задев молчавшую всё время Дашу."},{"kind":"paragraph","text":"— Ничего-ничего, — ответила Даша и отпила своё пиво."},{"kind":"paragraph","text":"— Как у тебя дела, Даша, что это ты всё молчишь? — обратился к девушке Пеймон."},{"kind":"paragraph","text":"— Да всё хорошо, музыку мне прикольно слушать под этим делом."},{"kind":"paragraph","text":"— А на учёбе как у тебя дела?"},{"kind":"paragraph","text":"— Неплохо. Одногруппники — быдло, но есть парочка нормальных."},{"kind":"paragraph","text":"— Так зови их всех в следующий раз, быдло особенно, — рассмеялся Пеймон."},{"kind":"paragraph","text":"От порошка Лину вставило так, что она практически не умолкала, в голову «дало» также Паше, и вписка начала, что называется, раскручиваться. Даже скромная Даша раскраснелась и явно повеселела, но складывалось ощущение, что это стало результатом скорее третьей бутылки пива, поскольку порошок не оказывал на неё столь существенного воздействия."},{"kind":"paragraph","text":"— Кры-ы-ы-ы-ы-ы-ы-ы-ыс! — заливался Пеймон, стаскивая с него одеяло. — Давай я тебе колёс дам, полегчает."},{"kind":"paragraph","text":"— У нас Пеймон — лучший доктор на районе, — прокомментировал Паша. — Хотел бы лечиться у такого, Орочи?"},{"kind":"paragraph","text":"— А то, от всех болезней!"},{"kind":"paragraph","text":"Крыса не отпускала одеяло, вгрызаясь в него, и Пеймон тянул на себя одеяло вместе с крысой. При этом крыса упиралась когтями в матрас."},{"kind":"paragraph","text":"— Да оставь его. Я думаю, ему уже лучше, — попросила Даша."},{"kind":"paragraph","text":"И действительно, вид крысы стал как-то посвежее, она отпустила одеяло и принялась выписывать круги по кровати, словно стремясь пожрать свой жёсткий короткий хвост."},{"kind":"paragraph","text":"— Смотри, как танцует, — заметил Орочимару."},{"kind":"paragraph","text":"— Я так же могу. Оп! — Паша стал танцевать под электронную музыку."},{"kind":"paragraph","text":"Чуть позже со своими неловкими движениями, включающими катание по полу, к нему присоединился Орочи."},{"kind":"paragraph","text":"Пеймон принёс откуда-то с кухни белую рифлёную таблеточку и дал сжевать её крысе."},{"kind":"paragraph","text":"— Сейчас вообще разъёб будет!"},{"kind":"paragraph","text":"— А мне? — обиженно сказала Лина."},{"kind":"paragraph","text":"— Ладно, возьми в тумбочке на кухне, но не больше двух."},{"kind":"paragraph","text":"Лина радостно убежала на кухню."},{"kind":"paragraph","text":"Крыса спрыгнула с кровати, выбежала в центр зала и стала исполнять совсем причудливый танец вокруг оброненной кем-то красной зажигалки."},{"kind":"paragraph","text":"— Тише, Паш, не зашиби её. Давай посмотрим."},{"kind":"paragraph","text":"Паша и Орочимару отошли в сторону, и все, включая вернувшуюся с кухни Лину, стали наблюдать за причудливыми движениями крысы, которые напоминали часть какого-то языческого ритуала. Подбегая к зажигалке спереди, крыса била хвостом в пол сначала вправо, потом влево; затем крыса возвращалась на исходную точку, перемещалась по часовой стрелке на девяносто градусов, вновь подбегала к зажигалке, вновь била хвостом об пол два раза и возвращалась назад. Затем крыса перемещалась ещё на девяносто градусов, и всё повторялось. Крыса кружила вокруг этой зажигалки по часовой стрелке не переставая, неуклонно соблюдая заданный алгоритм."},{"kind":"paragraph","text":"— Ишь, как её глючит! — сказал Орочи."},{"kind":"paragraph","text":"— Лучше крыса ШУЕ, чем крыса АУЕ*! — заметил Пеймон."},{"kind":"paragraph","text":"— Ладно, пускай развлекается, — сказал Паша. — Вы в курсе, что мы с Дашей выяснили, что у нас сигарет нет?"},{"kind":"paragraph","text":"— Да ладно, а «Ричмонд» мой? Скурили весь? — спросил Пеймон."},{"kind":"paragraph","text":"— Боюсь, что скури-и-и-или, — протянула Лина, облокачиваясь ему на плечо."},{"kind":"paragraph","text":"— Ладно, я схожу до магаза. — Пеймон, прихватив банковскую карточку, стал открывать дверь в подъезд в одной майке, тапках и спортивных штанах."},{"kind":"paragraph","text":"— Ты куда в таком виде? — спросила Лина."},{"kind":"paragraph","text":"— Мне похуй, я пойду так, мне жарко."},{"kind":"paragraph","text":"— В каком смысле «так»? — повысила голос Лина. — Вот увидишь: либо простудишься, либо заберут тебя."},{"kind":"paragraph","text":"— Мужчина знает свой путь! У меня здоровье железное! — отрезал Пеймон. — А впрочем, через окно быстрее будет."},{"kind":"paragraph","text":"— Ага, завтра на отходах мне это расскажешь! — крикнула Лина, а Пеймон прыгнул с балкона второго этажа в сугроб."},{"kind":"paragraph","text":"— С приземлением! — крикнул ему Паша."},{"kind":"paragraph","text":"— Сейчас, в пять минут обернусь! — ответил Пеймон."},{"kind":"paragraph","text":"Пеймон, весь мокрый, вернулся минут через пятнадцать с тремя пачками «Филип Моррис», чипсами, семью бутылками пива и двумя — игристого вина."},{"kind":"paragraph","text":"— До меня там алкаш какой-то ещё успел доебаться возле круглосуточного. Я его к нам звал — он не хочет."},{"kind":"paragraph","text":"— Так, иди в ванную, переодевайся, ты весь мокрый, — сказала встречавшая его Лина."},{"kind":"paragraph","text":"— У меня штаны только мокрые, — ответил Пеймон, сняв тёмно-синие спортивные штаны и оставшись в одной длинной майке, которая практически полностью скрывала трусы. Не став надевать что-то на замену, с обнажёнными худыми ногами, неся в руках два чёрных пакета, он прошёл в комнату."},{"kind":"paragraph","text":"Первой за сигарету взялась Даша, запивая её дым пивом. Парни также открыли пиво, кроме Орочи, который выстрелил с балкона пробкой игристого вина и принялся пить его из горла."},{"kind":"paragraph","text":"— Всё-таки иногда хочется вот так, вспомнить молодость. Можно, конечно, налить в стакан, но это всё не то, — сказал Орочи и чокнулся с ребятами."},{"kind":"paragraph","text":"Совершив множество оборотов вокруг зажигалки, крыса вдруг принялась, жёстко уперев глаза в пол, бегать из одного угла комнаты в другой."},{"kind":"paragraph","text":"— Вспоминаем геометрию: биссектриса — это крыса, бегает по углам, делит угол пополам, — отметил Пеймон."},{"kind":"paragraph","text":"— Крысик, тебе очень весело? — задала риторический вопрос Лина."},{"kind":"paragraph","text":"Даша молча сидела на кровати. Иногда к ней обращались Паша или Орочи с каким-то вопросом. Она не была особенно разговорчивой, но какого-то дискомфорта в такой обстановке она тоже не испытывала. Иначе вела себя Лина. За ночь она успела два раза поругаться и два раза помириться с Пеймоном, ловила за хвост крысу, случайно пролила вино на Пашину толстовку, пела и танцевала, обращалась с балкона к россиянам."},{"kind":"paragraph","text":"Примерно в половину первого прибыла вызванная соседкой из-за шума полиция. Пеймон, выйдя к ним в майке и трусах, пообещал, что музыка будет потише."},{"kind":"paragraph","text":"— Хотя она и так на полгромкости!"},{"kind":"paragraph","text":"— Ну это вы сейчас, наверное, потише сделали. Соседка ваша мне говорила, что у вас тут прямо концерт."},{"kind":"paragraph","text":"— Да сумасшедшая бабка, вы наверняка знаете таких по долгу службы. Она могла бы хоть сначала к нам сходить, попросить потише сделать."},{"kind":"paragraph","text":"— Ладно, ребят, в общем, закругляйтесь, и чтобы проблем больше сегодня не было! — сказал полицейский и ушёл со своим напарником во тьму подъезда, в котором ещё довольно давно перегорела одна из лампочек."},{"kind":"paragraph","text":"— Соседка — сука, — сказал Орочимару Пеймону, — и так ведь вполгромкости играло."},{"kind":"paragraph","text":"— Да тут стены как из картона — рукой пробить можно."},{"kind":"paragraph","text":"— Я уж думал оставшийся порошок в унитаз сливать, а потом как-то жалко стало. Подумал: не станут же они обыскивать нас — не тот вызов."},{"kind":"paragraph","text":"— Да я их изначально пускать не планировал, хотел на пороге поговорить, приняв на себя максимально адекватный вид. Вроде худо-бедно это удалось, так что правильно ты всё сделал."},{"kind":"paragraph","text":"— Вид у тебя, конечно, — верх адекватности! — саркастично заметил Орочимару, осмотрев Пеймона: без штанов, с глазами навыкате и разбросанными в электрическом хаосе прядями волос, частично прилипшими ко лбу из-за выступившего на нём пота."},{"kind":"paragraph","text":"Пеймон попросил отныне курить на кухне, так что гости периодически отлучались туда, стараясь не наступить на крысу. Когда весь алкоголь был выпит, Паша засобирался домой, сказав, что завтра в два часа он должен чем-то помочь отцу. Идти ему было недалеко. Орочи, живший вообще на другом конце города и под конец вечеринки сумевший-таки разговорить Дашу, примерно в пять утра стал вызывать себе такси. Когда Орочи уехал, Даша улеглась в углу кровати с телефоном, дожидаясь открытия метро. Крыса всё ещё бегала между углами комнаты, а Пеймон и Лина заперлись в тесном совмещённом санузле."},{"kind":"paragraph","text":"Вскоре из ванной послышался голос Лины:"},{"kind":"paragraph","text":"— Ты, придурок, перестань снимать!"},{"kind":"paragraph","text":"— Я не снимаю, мне Максим в телеге написывает, достал уже."},{"kind":"paragraph","text":"— Дай-ка тогда сюда телефон!"},{"kind":"paragraph","text":"— Линусик, да успокойся!"},{"kind":"paragraph","text":"— Соси себе сам тогда, или пускай тебе Максим сосёт, раз тебя переписка отвлекает!"},{"kind":"paragraph","text":"— Всё-всё, извини, пожалуйста."},{"kind":"paragraph","text":"Затем разговор в ванной комнате смолк. Крыса вышла на захламлённый балкон. На нём лежали без дела кое-какая разломанная советская мебель, которую давно пора было бы выбросить, подёрнутая ржавчиной решётка для гриля и кое-что из советского спортивного инвентаря: чугунная гиря на 16 кг, железный эспандер, одна лыжа чёрного цвета, на которой жёлтыми буквами было написано «Звезда». Часть хлама была скрыта куском зелёного брезента. Хотя все эти вещи хранились на балконе много лет, именно на следующий после вписки день Пеймон запланировал их капитальный разбор с выбросом всего ненужного."},{"kind":"paragraph","text":"По водосточной трубе крыса спустилась во двор. В такое время года в Санкт-Петербурге восход солнца ожидался не раньше половины десятого. Та «догонка» наркотиком с коробка была не лишней — крысу ещё заметно «подпирало». Медленно падали крупные хлопья снега, как бы накладывая фильтр на окружающий пейзаж. Крыса принялась обследовать окружающий её лабиринт хрущёвок на предмет закладок, желая запастись веществом впрок. Закладок нигде не было. В окнах начинал загораться свет — люди собирались на работу. Чуть позже люди стали покидать подъезды, расчищать свои машины от снега или двигаться в сторону метро. Кто-то вёл своих детей в детские сады и школы. В половине девятого была ещё темень, но во дворах вовсю проснулась жизнь. Постепенно воздух начал светлеть, тьма сменилась сумерками, в которых снежный ковёр приобрёл матовый тёмно-синий цвет."},{"kind":"paragraph","text":"С восходом солнца рыскающую по дворам крысу резко отпустило. Сперва она испугалась, что в своих поисках забралась так далеко от своего убежища. Казалось, что ушедшая на другую сторону планеты ночь обнажила всё уродство окружающего мира. Из-под колёс проезжающих по двору машин летела ледяная грязь. Крыса вскочила на сугроб возле обочины. Сугроб — это гора мельчайших кристалликов льда. Благороднейшая форма воды, изумительное произведение природы. Но стоило крысе попытаться разрыть сугроб, чтобы хотя бы на время, подобно страусу, спрятать туда голову, охладить её от переполнявших мыслей, — как крыса увидела, что под тонким белым слоем снег меняет свой цвет. Чуть ниже снег становится бежевым, то есть уже успевшим впитать в себя зловонное дыхание окружающего города. Эти упавшие с небес чистые кристаллы воды вобрали в себя сажу, бензпирен, антрацен, альдегиды, монооксид углерода, оксиды азота и прочие токсичные химические соединения. Благородный, чистый материал оказался безнадёжно отравлен. Крысу привёл в ужас вспомнившийся ей иссиня-чёрный заледеневший снег, неделями лежавший возле автомобильных дорог. Нужно было срочно добираться до своего подвала."},{"kind":"paragraph","text":"Но двигаться стало очень страшно. Крыса начала бояться случайных прохожих. Ей казалось, что проходящий мимо человек может коротким и резким ударом ноги просто переломить ей позвоночник. Она вспомнила, как около двух недель назад видела труп другой, очень тощей крысы с переломанным позвоночником, лежавший за окраинным торговым центром неподалёку от её дома. Пробираясь вдоль стен, прячась от людей, примерно за двадцать пять минут крысе удалось добраться до знакомого вентиляционного отверстия и нырнуть в свой подвал. От тревоги её всю трясло. Снюхав дорогу со спичечного коробка «ПЕРВЫЙ СОВЕТСКИЙ ЭЛЕКТРОВОЗ 1932», крыса примерно в течение пятнадцати секунд пришла в себя."},{"kind":"paragraph","text":"Крыса давно чувствовала усталость от постоянной необходимости экстренного поиска дозы, когда отходняки уже подбираются вплотную к организму. Поэтому давно уже она приняла решение создавать пополняемый запас наркотика, который служил бы ей «подушкой безопасности» на случай, если вовремя найти очередную дозу не удастся. Однако, по всей видимости, район её обитания перестал пользоваться такой популярностью среди закладчиков. Она отчётливо подметила: в последний месяц находить здесь наркотики стало сложнее."},{"kind":"paragraph","text":"Крыса знала, что самое большое изобилие закладок находится чуть за городом, за одной из лесных полян, которая уже стала знаменитой среди питерских наркоманов. Однажды она ездила туда на такси с Пеймоном и Линой — девушка нехотя впустила её в свою сумку, чтобы дополнительно не смущать таксиста, который и так, очевидно понимая, что находится в пункте назначения, был не в восторге от того, что ему приходится везти наркоманов. Иногда крыса выглядывала из сумки и смотрела в окно и в общем сумела запомнить этот несложный маршрут. Нужно было всего лишь двигаться по тому же Ленинскому проспекту на север, покинуть городскую черту и остановиться на обочине у одной из просёлочных дорог. Таков был маршрут для таксиста. Дальше нужно было идти пешком по просёлочной дороге, перегороженной в одном месте двумя бетонными блоками, которые препятствовали проезду автомобилей. Минут через пять-семь можно было выйти на лесную опушку, в чаще за которой находилось больше всего «кладов»."},{"kind":"paragraph","text":"Конечно, добираться для неё туда было проблематично. На такси от дома Пеймона ехали всего минут двадцать. Но такси крыса вызвать себе не могла. Можно было попытаться добраться быстрее: запрыгнуть в одну из маршруток, которые едут в нужную ей сторону по Ленинскому проспекту, и выпрыгнуть из неё на одной из остановок поближе к черте города. Это существенно облегчило бы задачу, однако, по всей видимости, такой способ перемещения был для крысы невозможен. Залезь она в эту маршрутную «Газель», плотно набившиеся туда пассажиры были бы в негодовании. Кто-то, возможно, отказался бы ехать, пока крыса не покинет транспорт, а кто-то из мужчин и вовсе мог попытаться убить её. Так что оставался один вариант — добираться своим ходом. Пешком, по приблизительным подсчётам крысы, дорога лишь в одну сторону займёт порядка двух часов. Можно было чуть увеличить скорость своего движения, «догнавшись» мефом, что крыса и сделала, правда, очень экономно, поскольку, во-первых, её и так неплохо «вставило», а во-вторых, оставался риск вообще ничего в этом лесу не найти. Начертив своими коготочками «мини-дорожку» на вырезке из советской газеты, на которой располагалась статья «Трудящиеся колхоза \"Светлый путь\" перевыполнили план по добыче зерна», крыса снюхала порошок, отчего всё её тело несколько раз передёрнуло."},{"kind":"paragraph","text":"Снова ждать темноты не было смысла. Едва ли люди, повстречавшиеся крысе при свете дня, могли помешать осуществлению её плана. На своей наркотической батарейке «городскую» половину пути крыса преодолела одним махом и относительно легко, подустав лишь под конец. Она решила прилечь на высокий чёрный сугроб на обочине дороги и перевести дух. С самого утра чуть потеплело, и природа начала подтаивать. Из-под колёс проносящихся машин летели чёрные плевки грязи. Начавший таять чёрный сугроб впивался в тельце крысы своими острыми ледяными углами. Самой же крысе нравилось отдыхать на этом небольшом возвышении. Она озирала автомобильные развязки, цветастые новостройки, коробки пригородных гипермаркетов и строительных магазинов."},{"kind":"paragraph","text":"Продолжив путь и выйдя в итоге на нужное место, крыса миновала поляну и приступила к работе. После часа безуспешных поисков её стало настигать разочарование. Обида усиливалась тем, что на её глазах в лес вбегали люди, судорожно сверяя что-то в телефоне, и уходили с «кладом» в течение всего нескольких минут. Ко всему прочему, крыса начала чувствовать, как ослабевает действие наркотика. Наконец в чащу вошли двое ребят, на вид старшеклассников."},{"kind":"paragraph","text":"— Куда здесь, Никит?"},{"kind":"paragraph","text":"— А вон под той рогатиной нужно копать, судя по стрелочке."},{"kind":"paragraph","text":"Ребята подошли к чёрной трухлявой коряге, которая двумя своими рогами напоминала изображение Бафомета."},{"kind":"paragraph","text":"— Здесь?"},{"kind":"paragraph","text":"— Кажется, да!"},{"kind":"paragraph","text":"Никита достал складной ножик и спустя несколько минут раскопок вытащил на свет прозрачный пакетик с горстью белых таблеток."},{"kind":"paragraph","text":"— Ну что, по две сейчас вкинем?"},{"kind":"paragraph","text":"— Ага. А ты посмотри, кто к нам явился! И не боится совсем!"},{"kind":"paragraph","text":"Крыса подошла к ребятам почти вплотную и просительно вытянула морду, снизу глядя на таблетки."},{"kind":"paragraph","text":"— Ух ты, напугала она меня! Может, бешеная или ещё чего? Вообще-то, такие животные дичатся человека, не приближаются."},{"kind":"paragraph","text":"— Сам ты дикий человек! Она ручная, значит, раз к человеку подходит."},{"kind":"paragraph","text":"— Да ну её! Давай вкинем — и до остановки, ехать пора!"},{"kind":"paragraph","text":"— Да подожди ты! — Молодой человек взял из пакетика таблетку и протянул крысе. Та схватила её и убежала вглубь чащи."},{"kind":"paragraph","text":"— С ума сошёл! Ты чего животных травишь?"},{"kind":"paragraph","text":"— Да пусть кайфанёт, у неё, я думаю, жизнь не сахар. Дома нет. Интернета, центрального отопления тоже. Тем более, как я слышал, учёные опыты ставят, крысам наркотики дают!"},{"kind":"paragraph","text":"— Ладно, ешь сам давай, и пойдём уже."},{"kind":"paragraph","text":"Горькая таблетка, вкус которой крыса безуспешно пыталась перебить, пережёвывая слежавшийся снег, подарила ей спокойствие и умиротворение вместе с лёгкой эйфорией. Хотелось неторопливо, лёгкой трусцой передвигаться по этому смешанному зимнему лесу и вдыхать его воздух. После пары часов прогулки крыса стала ощущать, насколько её тельце насытилось кислородом. Она начала чувствовать свой кровоток, а в конечностях возникло приятное покалывание. Незаметно для себя она выбежала к какому-то садоводству, пустынному в это время года."},{"kind":"paragraph","text":"Садоводство выглядело голо и неуютно. Оно не было покрыто снегом, который таял всё сильнее, выводя на передний план запущенность места с его покосившимися заборами, по большей части полуразрушенными, деревянными домиками, гниющими либо обугленными, выбоинами на дорогах, наполненными какой-то тёмно-серой жижей. Хотя отдельные участки «шестисотки» отличались почти европейской аккуратностью, общего впечатления от места это не меняло."},{"kind":"paragraph","text":"Бредя по обочине одной из пустынных улиц этого садоводства, крыса начала чувствовать голод. Из-за наркотиков она могла не испытывать это чувство по нескольку дней, однако потом её желудок буквально начинало сводить судорогами. Вдалеке, на пересечении нескольких улиц, крыса увидела главный сельский магазин. Он представлял собой большой ларёк из ярко-синего профлиста. Магазин был заперт, да и наивно было надеяться стащить там что-либо."},{"kind":"paragraph","text":"Зато чуть дальше, сбоку от этого пересечения улиц, в железном баке горел костёр, и рядом с ним переминались с ноги на ногу два бомжа совсем запущенного вида, каких сейчас почти и не встретишь, с перепачканными сажей лицами и косматыми бородами. Они прямо на открытом огне жарили кусочки какого-то мяса, разложенного на разломанной наполовину решётке для гриля, очевидно, найденной ими на ближайшей помойке."},{"kind":"paragraph","text":"— Ну шо, Рыло?! Обед к нам сам идёт? — прохрипел первый бомж, в тёмно-зелёной шапке, завидев подошедшую к ним крысу."},{"kind":"paragraph","text":"— А хуй ты поймаешь её, их спящих глушат! — пробасил второй бомж, достал из-за пазухи бутылку водки «Путинка» и сделал добрый глоток."},{"kind":"paragraph","text":"— Попытка не пытка, ёптыть!"},{"kind":"paragraph","text":"— Ну ладно, изловим."},{"kind":"paragraph","text":"Поняв, что лучше ей убираться, крыса попыталась бежать. Однако тело плохо слушалось её, лапы заплетались, и в итоге она упала животом на зерно щебня, что могло бы быть очень болезненно, если бы не действие опиатов."},{"kind":"paragraph","text":"Подбежавший бомж Рыло тут же схватил её в свою шершавую, покрытую чёрным налётом ладонь."},{"kind":"paragraph","text":"— Водки, шо ль, набухалась? Еле движется."},{"kind":"paragraph","text":"— Тащи её сюда, сейчас разделывать будем."},{"kind":"paragraph","text":"Бомж в зелёной шапке достал перочинный нож, сделал на крысе несколько надрезов и стянул с неё шкуру, обнажив розовое тельце. Крыса почувствовала, как ветер стал приятно обдувать её кожу, и исходившее от костра тепло стало ощущаться явственнее."},{"kind":"paragraph","text":"— Слух, а что мы всё жарим живность? Я на помойке фольгу видел — давай в углях запечём целую?"},{"kind":"paragraph","text":"— А давай!"},{"kind":"paragraph","text":"Бомж в зелёной шапке отлучился на свалку, а его товарищ стал готовить угли: ломом выбросил из бака пару горящих поленьев, а уже почти догоравшие — добил и разломал. Голую крысу укутали в принесённую вторым бомжом фольгу и поместили её в угли — в самое пекло бака. В его железном нутре крысе было тепло и приятно. Постепенно согреваясь, она стала засыпать."},{"kind":"paragraph","text":"Ей стало сниться, что она находится на залитой солнцем площади небольшого провинциального городка перед Домом культуры. Судя по отсутствию рекламы, автомобилям (и их малому количеству), одежде прохожих, — были шестидесятые годы. На площади вокруг памятника Ленину были рассажены тюльпаны, а чуть ближе к прилегающему проспекту располагался небольшой фонтан. Вокруг него на скамейках отдыхали граждане, до которых иногда долетали небольшие брызги. Кто-то читал газету, кто-то играл в шахматы или «резался» в домино. Гуляли молодые мамы с колясками. Дети постарше резвились уже самостоятельно: играли в мяч, в «пятнашки», пускали мыльные пузыри. Кто-то ел мороженое и пил газировку возле автомата. Постепенно солнечный день стал сменяться тучами. Среди публики, присутствующей на площади, стали появляться «сомнительные» элементы. Их принадлежность к уголовному или просто маргинальному миру выдавали повадки, татуировки, хмурые и злые лица с грубыми чертами. Изначально присутствовавшая на площади публика, которая так понравилась крысе, напротив, стала редеть и постепенно растворяться в окрестных улицах и домах. Темнело. Среди «грубой» публики начал складываться стихийный митинг. Какой-то явно подвыпивший очень тощий мужчина в тельняшке и с трёхдневной щетиной залез в фонтан и хриплым голосом принялся кричать: «ХРУЩЁВА ПУСТИМ НА МЯСО!» Ему начал вторить нестройный хор таких же хриплых голосов. Лозунг «Хрущёва на мясо» сменился лозунгом «Хрущёва на колбасу», а потом откуда-то появились плакаты «ПОЖАРИМ ХРУЩЁВА НА ОГРОМНОЙ СКОВОРОДЕ СОЦИАЛИЗМА!» и «ХРУЩЁВА НОЖАМИ ПОРЕЖЕМ НА ЧАСТИ! ЛЕНИН ВОССТАНЕТ, И БУДЕТ ВСЕМ СЧАСТЬЕ!»."},{"kind":"paragraph","text":"Один из мужиков схватил вскочившую на скамейку крысу и мёртвой хваткой сдавил ей шею. Внутри неё что-то хрустнуло, она почувствовала невыносимый жар и провалилась во тьму."},{"kind":"paragraph","text":"*Правительственные органы страны России признали АУЕ экстремистской организацией, будьте бдительны."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
