INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd5-sohrannost',
  'Сохранность',
  (SELECT id FROM "Authors" WHERE name = 'Ада Вильк' ORDER BY id LIMIT 1),
  'mrd5/mrd5-sohrannost.jpg',
  'data:image/jpeg;base64,',
  1600,
  923,
  '<об антицелостности>',
  '[{"kind":"image","path":"mrd5/mrd5-sohrannost.jpg","caption":"Иллюстрация Екатерины Ковалевской"},{"kind":"paragraph","text":"<об антицелостности>"},{"kind":"paragraph","text":"Пространство пережёвывает меня жвачкой и выдувает пузыри, выдавливает пузыри моих глаз, и я, свободный от картинок, иду подсматривать за чужим дефицитом жизни, которого тем не менее никто не желает себя лишать. За людьми, целующими румяный зад реальности, за их страхом вывалиться за рамочку пространства. И мне приятно швырять в них свои глаза. Чтобы они катали их за слизнями губ, как ребёнок катает леденец за розовой щекой. И что я разодран на запчасти. Приятно знать, что я — икеевское недоразумение. Разобран на запчасти, и мне больше не надо ощущать себя как единое целое."},{"kind":"paragraph","text":">¡<"},{"kind":"paragraph","text":"Если выбирать, в кого превратиться, то я тоже выберу насекомое. И, пожалуй, из всех беспозвоночно-членистоногих аппетит моего сердца принадлежит мотыльку: бледный/обезопасившийся — положительно незаинтересованный под стеклом экзиста, но вдавленный в существование булавкой. Её железный фаллос пронзает моё брюхо — и это настоящее счастье. Потому что я намертво (действительно) вколот в жизнь."},{"kind":"paragraph","text":"Высохшее насекомое. Но это обращение лучше разинутой вечности. Меня воротит от мысли, что я нахожусь между двумя коконами: рождением и той самой."},{"kind":"paragraph","text":"Не хочу упаковываться и заматываться обратно."},{"kind":"paragraph","text":"Ведь это абсолютная благодать — быть утихомирившим крылья мотыльком, которого не освободить от булавки — иначе он раскрошится, облетит (не комнату). Бесценная тушка, вцепившаяся в остриё, просто боится. Но разве — стыдно?"},{"kind":"paragraph","text":"И здесь я ничего не скажу о привлекательности света для насекомых: меня не пленит идея встречи салемской инквизиции. Просто я люблю свою чешуекрылость, и нет ничего хуже — чем подарить её той, чьи неизживные руки запятнаны пыльцой."},{"kind":"paragraph","text":"А я вдруг вспомнил, что умею мотылять."},{"kind":"paragraph","text":"Не так ли?"},{"kind":"paragraph","text":"<реверс>"},{"kind":"paragraph","text":"Я дышу на стекло и рисую розовым пальцем лицо. Сегодня мне исполнилось семь, и ничего не изменилось."},{"kind":"paragraph","text":"Мы сидим с матерью в машине, выхлопная труба изливает в пространство белый дым. Одно из первых эротических впечатлений."},{"kind":"paragraph","text":"Сейчас, в свои тридцать три, мне хотелось притвориться, что я действительно нарисовал лицо: кривую улыбку и две точки глаз. Но я не нарисовал. Засмотревшись на выхлопную трубу, я на автомате нарисовал член. Так бывает, когда замираешь с маркером перед забором, но вместо Мадонны сознание выдаёт то, что Мадонне возможность познать не представилась."},{"kind":"paragraph","text":"Через свой рисунок я смотрел на мир вокруг и видел его в первый раз."},{"kind":"paragraph","text":"Мать наконец прогрела машину, и мы двинулись."},{"kind":"paragraph","text":"Преувеличенное достоинство открывало передо мной все возможности перспективы."},{"kind":"paragraph","text":"Нанизанные на слюну проводов цветные конфеты фонарей разукрасили мой рисунок вангоговским спектром."},{"kind":"paragraph","text":"И тогда я был убеждён, что абсолютно счастлив."},{"kind":"paragraph","text":"Рассказ победителя четвёртого сезона конкурса рок-прозы «Гроза»."}]'::jsonb,
  '2024-01-20T12:00:00.000Z'
)
